insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a79dc0f2-760e-54f8-af55-e4cbb73ca562', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '168', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏وَأَبُو عَلْقَمَةَ الْفَرْوِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يَبْعَثُ رِيحًا مِنْ ‏ ‏الْيَمَنِ ‏ ‏أَلْيَنَ مِنْ الْحَرِيرِ فَلَا تَدَعُ أَحَدًا فِي قَلْبِهِ ‏ ‏قَالَ ‏ ‏أَبُو عَلْقَمَةَ ‏ ‏مِثْقَالُ حَبَّةٍ ‏ ‏و قَالَ ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏مِثْقَالُ ذَرَّةٍ ‏ ‏مِنْ إِيمَانٍ إِلَّا قَبَضَتْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2e772b37-8156-5de8-87a6-97efbb322e22', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '169', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَابْنُ حُجْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا بِالْأَعْمَالِ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا أَوْ يُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا يَبِيعُ دِينَهُ ‏ ‏بِعَرَضٍ ‏ ‏مِنْ الدُّنْيَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b13257b1-a2bd-555f-b16f-96c08efa04b8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '170', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ ‏} ‏إِلَى آخِرِ الْآيَةِ جَلَسَ ‏ ‏ثَابِتُ بْنُ قَيْسٍ ‏ ‏فِي بَيْتِهِ وَقَالَ أَنَا مِنْ أَهْلِ النَّارِ وَاحْتَبَسَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏مَا شَأْنُ ‏ ‏ثَابِتٍ ‏ ‏اشْتَكَى ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏إِنَّهُ لَجَارِي وَمَا عَلِمْتُ لَهُ بِشَكْوَى قَالَ فَأَتَاهُ ‏ ‏سَعْدٌ ‏ ‏فَذَكَرَ لَهُ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏ثَابِتٌ ‏ ‏أُنْزِلَتْ هَذِهِ الْآيَةُ وَلَقَدْ عَلِمْتُمْ أَنِّي مِنْ أَرْفَعِكُمْ صَوْتًا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنَا مِنْ أَهْلِ النَّارِ فَذَكَرَ ذَلِكَ ‏ ‏سَعْدٌ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ هُوَ مِنْ أَهْلِ الْجَنَّةِ ‏ ‏و حَدَّثَنَا ‏ ‏قَطَنُ بْنُ نُسَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ ‏ ‏خَطِيبَ ‏ ‏الْأَنْصَارِ ‏ ‏فَلَمَّا نَزَلَتْ هَذِهِ الْآيَةُ بِنَحْوِ حَدِيثِ ‏ ‏حَمَّادٍ ‏ ‏وَلَيْسَ فِي حَدِيثِهِ ذِكْرُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏و حَدَّثَنِيهِ ‏ ‏أَحْمَدُ بْنُ سَعِيدِ بْنِ صَخْرٍ الدَّارِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَبَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ ‏} ‏وَلَمْ يَذْكُرْ ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏فِي الْحَدِيثِ ‏ ‏و حَدَّثَنَا ‏ ‏هُرَيْمُ بْنُ عَبْدِ الْأَعْلَى الْأَسَدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَذْكُرُ عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ وَاقْتَصَّ الْحَدِيثَ وَلَمْ يَذْكُرْ ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏وَزَادَ فَكُنَّا ‏ ‏نَرَاهُ يَمْشِي بَيْنَ أَظْهُرِنَا رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c42c6b2d-1780-583c-959f-fcb1e9cd7924', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '171', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ أُنَاسٌ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ أَنُؤَاخَذُ بِمَا عَمِلْنَا فِي الْجَاهِلِيَّةِ قَالَ ‏ ‏أَمَّا مَنْ أَحْسَنَ مِنْكُمْ فِي الْإِسْلَامِ فَلَا يُؤَاخَذُ بِهَا وَمَنْ أَسَاءَ أُخِذَ بِعَمَلِهِ فِي الْجَاهِلِيَّةِ وَالْإِسْلَامِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d422905d-041d-5a7a-9ac0-107ef488169d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '172', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ أَنُؤَاخَذُ بِمَا عَمِلْنَا فِي الْجَاهِلِيَّةِ قَالَ ‏ ‏مَنْ أَحْسَنَ فِي الْإِسْلَامِ لَمْ يُؤَاخَذْ بِمَا عَمِلَ فِي الْجَاهِلِيَّةِ وَمَنْ أَسَاءَ فِي الْإِسْلَامِ أُخِذَ بِالْأَوَّلِ وَالْآخِرِ ‏ ‏حَدَّثَنَا ‏ ‏مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b9c84159-336d-5100-bea0-cbe3e7cede56', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '173', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى الْعَنَزِيُّ ‏ ‏وَأَبُو مَعْنٍ الرَّقَاشِيُّ ‏ ‏وَإِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏أَبِي عَاصِمٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِابْنِ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ يَعْنِي أَبَا عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِمَاسَةَ الْمَهْرِيِّ ‏ ‏قَالَ ‏ ‏حَضَرْنَا ‏ ‏عَمْرَو بْنَ الْعَاصِ ‏ ‏وَهُوَ ‏ ‏فِي سِيَاقَةِ ‏ ‏الْمَوْتِ فَبَكَى طَوِيلًا وَحَوَّلَ وَجْهَهُ إِلَى الْجِدَارِ فَجَعَلَ ابْنُهُ يَقُولُ يَا أَبَتَاهُ أَمَا بَشَّرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَذَا أَمَا بَشَّرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَذَا قَالَ فَأَقْبَلَ بِوَجْهِهِ فَقَالَ إِنَّ أَفْضَلَ مَا نُعِدُّ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏إِنِّي كُنْتُ عَلَى أَطْبَاقٍ ثَلَاثٍ لَقَدْ رَأَيْتُنِي وَمَا أَحَدٌ أَشَدَّ بُغْضًا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنِّي وَلَا أَحَبَّ إِلَيَّ أَنْ أَكُونَ قَدْ اسْتَمْكَنْتُ مِنْهُ فَقَتَلْتُهُ فَلَوْ مُتُّ عَلَى تِلْكَ الْحَالِ لَكُنْتُ مِنْ أَهْلِ النَّارِ فَلَمَّا جَعَلَ اللَّهُ الْإِسْلَامَ فِي قَلْبِي أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ابْسُطْ يَمِينَكَ فَلْأُبَايِعْكَ فَبَسَطَ يَمِينَهُ قَالَ فَقَبَضْتُ يَدِي قَالَ مَا لَكَ يَا ‏ ‏عَمْرُو ‏ ‏قَالَ قُلْتُ أَرَدْتُ أَنْ أَشْتَرِطَ قَالَ تَشْتَرِطُ بِمَاذَا قُلْتُ أَنْ يُغْفَرَ لِي قَالَ ‏ ‏أَمَا عَلِمْتَ أَنَّ الْإِسْلَامَ يَهْدِمُ مَا كَانَ قَبْلَهُ وَأَنَّ الْهِجْرَةَ تَهْدِمُ مَا كَانَ قَبْلِهَا وَأَنَّ الْحَجَّ يَهْدِمُ مَا كَانَ قَبْلَهُ وَمَا كَانَ أَحَدٌ أَحَبَّ إِلَيَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا أَجَلَّ فِي عَيْنِي مِنْهُ وَمَا كُنْتُ أُطِيقُ أَنْ أَمْلَأَ عَيْنَيَّ مِنْهُ إِجْلَالًا لَهُ وَلَوْ سُئِلْتُ أَنْ أَصِفَهُ مَا أَطَقْتُ لِأَنِّي لَمْ أَكُنْ أَمْلَأُ عَيْنَيَّ مِنْهُ وَلَوْ مُتُّ عَلَى تِلْكَ الْحَالِ لَرَجَوْتُ أَنْ أَكُونَ مِنْ أَهْلِ الْجَنَّةِ ثُمَّ وَلِينَا أَشْيَاءَ مَا أَدْرِي مَا حَالِي فِيهَا فَإِذَا أَنَا مُتُّ فَلَا تَصْحَبْنِي نَائِحَةٌ وَلَا نَارٌ فَإِذَا دَفَنْتُمُونِي ‏ ‏فَشُنُّوا ‏ ‏عَلَيَّ التُّرَابَ شَنًّا ثُمَّ أَقِيمُوا حَوْلَ قَبْرِي قَدْرَ مَا تُنْحَرُ ‏ ‏جَزُورٌ ‏ ‏وَيُقْسَمُ لَحْمُهَا حَتَّى أَسْتَأْنِسَ بِكُمْ وَأَنْظُرَ مَاذَا أُرَاجِعُ بِهِ رُسُلَ رَبِّي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b2af38ba-2ecd-5d0c-985d-5e731b7890e4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '174', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ ‏ ‏وَإِبْرَاهِيمُ بْنُ دِينَارٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَجَّاجٌ وَهُوَ ابْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ مُسْلِمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَاسًا مِنْ أَهْلِ الشِّرْكِ قَتَلُوا فَأَكْثَرُوا وَزَنَوْا فَأَكْثَرُوا ثُمَّ أَتَوْا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّ الَّذِي تَقُولُ وَتَدْعُو لَحَسَنٌ وَلَوْ تُخْبِرُنَا أَنَّ لِمَا عَمِلْنَا كَفَّارَةً فَنَزَلَ ‏ { ‏وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ ‏ ‏أَثَامًا ‏ } ‏وَنَزَلَ ‏ { ‏يَا ‏ ‏عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا ‏ ‏تَقْنَطُوا ‏ ‏مِنْ رَحْمَةِ اللَّهِ ‏}', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1d839354-374d-5627-b9c4-bf78abdb998c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '175', '‏ ‏حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ أُمُورًا كُنْتُ ‏ ‏أَتَحَنَّثُ ‏ ‏بِهَا فِي الْجَاهِلِيَّةِ هَلْ لِي فِيهَا مِنْ شَيْءٍ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمْتَ عَلَى مَا ‏ ‏أَسْلَفْتَ ‏ ‏مِنْ خَيْرٍ ‏ ‏وَالتَّحَنُّثُ التَّعَبُّدُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('308a0b62-5fc9-5175-8b32-119d8c025948', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '176', '‏ ‏و حَدَّثَنَا ‏ ‏حَسَنٌ الْحُلْوَانِيُّ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَ ‏ ‏الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏وَقَالَ ‏ ‏عَبْدٌ ‏ ‏حَدَّثَنِي ‏ ‏يَعْقُوبُ وَهُوَ ابْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْ رَسُولَ اللَّهِ أَرَأَيْتَ أُمُورًا كُنْتُ ‏ ‏أَتَحَنَّثُ ‏ ‏بِهَا فِي الْجَاهِلِيَّةِ مِنْ صَدَقَةٍ أَوْ ‏ ‏عَتَاقَةٍ ‏ ‏أَوْ صِلَةِ رَحِمٍ أَفِيهَا أَجْرٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمْتَ عَلَى مَا ‏ ‏أَسْلَفْتَ ‏ ‏مِنْ خَيْرٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('71478433-02d9-5abf-b1cf-f0e1ae51a972', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '177', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَشْيَاءَ كُنْتُ أَفْعَلُهَا فِي الْجَاهِلِيَّةِ ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏يَعْنِي ‏ ‏أَتَبَرَّرُ ‏ ‏بِهَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمْتَ عَلَى مَا ‏ ‏أَسْلَفْتَ ‏ ‏لَكَ مِنْ الْخَيْرِ قُلْتُ فَوَاللَّهِ لَا أَدَعُ شَيْئًا صَنَعْتُهُ فِي الْجَاهِلِيَّةِ إِلَّا فَعَلْتُ فِي الْإِسْلَامِ مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏أَعْتَقَ فِي الْجَاهِلِيَّةِ مِائَةَ رَقَبَةٍ وَحَمَلَ عَلَى مِائَةِ بَعِيرٍ ثُمَّ أَعْتَقَ فِي الْإِسْلَامِ مِائَةَ رَقَبَةٍ وَحَمَلَ عَلَى مِائَةِ بَعِيرٍ ثُمَّ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِهِمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('397e8aa6-453a-5fe3-8a8e-0f14c8b171c6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '178', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏الَّذِينَ آمَنُوا وَلَمْ ‏ ‏يَلْبِسُوا ‏ ‏إِيمَانَهُمْ ‏ ‏بِظُلْمٍ ‏ } ‏شَقَّ ذَلِكَ عَلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالُوا أَيُّنَا لَا يَظْلِمُ نَفْسَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ هُوَ كَمَا تَظُنُّونَ إِنَّمَا هُوَ كَمَا قَالَ ‏ ‏لُقْمَانُ ‏ ‏لِابْنِهِ ‏ { ‏يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ‏} ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَلِيُّ بْنُ خَشْرَمٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عِيسَى وَهُوَ ابْنُ يُونُسَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ مُسْهِرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏أَبُو كُرَيْبٍ ‏ ‏قَالَ ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏حَدَّثَنِيهِ ‏ ‏أَوَّلًا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ تَغْلِبَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏ثُمَّ ‏ ‏سَمِعْتُهُ مِنْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e460c3b3-be4c-5209-b238-30114072e2ac', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '179', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مِنْهَالٍ الضَّرِيرُ ‏ ‏وَأُمَيَّةُ بْنُ بِسْطَامَ الْعَيْشِيُّ ‏ ‏وَاللَّفْظُ ‏ ‏لِأُمَيَّةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ وَهُوَ ابْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الْأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏} ‏قَالَ فَاشْتَدَّ ذَلِكَ عَلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ بَرَكُوا عَلَى الرُّكَبِ فَقَالُوا أَيْ رَسُولَ اللَّهِ كُلِّفْنَا مِنْ الْأَعْمَالِ مَا نُطِيقُ الصَّلَاةَ وَالصِّيَامَ وَالْجِهَادَ وَالصَّدَقَةَ وَقَدْ أُنْزِلَتْ عَلَيْكَ هَذِهِ الْآيَةُ وَلَا نُطِيقُهَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الْكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا بَلْ قُولُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ قَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ فَلَمَّا اقْتَرَأَهَا الْقَوْمُ ذَلَّتْ بِهَا أَلْسِنَتُهُمْ فَأَنْزَلَ اللَّهُ فِي ‏ ‏إِثْرِهَا ‏ { ‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏} ‏فَلَمَّا فَعَلُوا ذَلِكَ نَسَخَهَا اللَّهُ تَعَالَى فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا ‏ ‏وُسْعَهَا ‏ ‏لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏} ‏قَالَ نَعَمْ ‏ { ‏رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا ‏ ‏إِصْرًا ‏ ‏كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏} ‏قَالَ نَعَمْ ‏ { ‏رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ‏} ‏قَالَ نَعَمْ ‏ { ‏وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ‏} ‏قَالَ نَعَمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('99cc4f97-1d9e-5129-9aa9-ca3525060133', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '180', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏آدَمَ بْنِ سُلَيْمَانَ ‏ ‏مَوْلَى ‏ ‏خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ ‏} ‏قَالَ دَخَلَ قُلُوبَهُمْ مِنْهَا شَيْءٌ لَمْ يَدْخُلْ قُلُوبَهُمْ مِنْ شَيْءٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُولُوا سَمِعْنَا وَأَطَعْنَا وَسَلَّمْنَا قَالَ فَأَلْقَى اللَّهُ الْإِيمَانَ فِي قُلُوبِهِمْ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا ‏ ‏وُسْعَهَا ‏ ‏لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏} ‏قَالَ قَدْ فَعَلْتُ ‏ { ‏رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا ‏ ‏إِصْرًا ‏ ‏كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏} ‏قَالَ قَدْ فَعَلْتُ ‏ { ‏وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا ‏} ‏قَالَ قَدْ فَعَلْتُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
