insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eea264e3-f053-5da3-a0dc-e0e530c7d5c3', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '1', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ بْنِ قَعْنَبٍ الْقَعْنَبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ذَهَبَ الْمَذْهَبَ أَبْعَدَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('66275fe1-afac-5121-98b8-70349963d8e8', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '2', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدُ بْنُ مُسَرْهَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَرَادَ الْبَرَازَ انْطَلَقَ حَتَّى لَا يَرَاهُ أَحَدٌ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eeef01eb-7741-5a77-ade5-fcf206b77d86', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '3', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَيْخٌ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏الْبَصْرَةَ ‏ ‏فَكَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏فَكَتَبَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِلَى ‏ ‏أَبِي مُوسَى ‏ ‏يَسْأَلُهُ عَنْ أَشْيَاءَ ‏ ‏فَكَتَبَ إِلَيْهِ ‏ ‏أَبُو مُوسَى ‏ ‏إِنِّي كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَأَرَادَ أَنْ يَبُولَ فَأَتَى ‏ ‏دَمِثًا ‏ ‏فِي أَصْلِ جِدَارٍ فَبَالَ ثُمَّ قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَبُولَ ‏ ‏فَلْيَرْتَدْ ‏ ‏لِبَوْلِهِ مَوْضِعًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8cf56a5a-01d0-54eb-aa93-da8a0ab40440', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '4', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدُ بْنُ مُسَرْهَدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏وَعَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْخَلَاءَ ‏ ‏قَالَ عَنْ ‏ ‏حَمَّادٍ ‏ ‏قَالَ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ ‏ ‏وَقَالَ عَنْ ‏ ‏عَبْدِ الْوَارِثِ ‏ ‏قَالَ ‏ ‏أَعُوذُ بِاللَّهِ ‏ ‏مِنْ ‏ ‏الْخُبُثِ ‏ ‏وَالْخَبَائِثِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ ‏ ‏وَقَالَ مَرَّةً أَعُوذُ بِاللَّهِ ‏ ‏و قَالَ ‏ ‏وُهَيْبٌ ‏ ‏فَلْيَتَعَوَّذْ بِاللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَمْرٍو يَعْنِي السَّدُوسِيَّ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ هُوَ ابْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏بِهَذَا الْحَدِيثِ قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ ‏ ‏وَقَالَ ‏ ‏شُعْبَةُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً أَعُوذُ بِاللَّهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fba3e336-8697-51b0-bbbe-5035cc333e55', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '5', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مَرْزُوقٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏النَّضِرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ هَذِهِ ‏ ‏الْحُشُوشَ ‏ ‏مُحْتَضَرَةٌ ‏ ‏فَإِذَا أَتَى أَحَدُكُمْ الْخَلَاءَ فَلْيَقُلْ أَعُوذُ بِاللَّهِ مِنْ ‏ ‏الْخُبُثِ ‏ ‏وَالْخَبَائِثِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e0fa24ff-5b5c-5143-aca9-a4cd33092319', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '6', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدُ بْنُ مُسَرْهَدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏قِيلَ لَهُ لَقَدْ عَلَّمَكُمْ نَبِيُّكُمْ كُلَّ شَيْءٍ حَتَّى الْخِرَاءَةَ قَالَ أَجَلْ لَقَدْ ‏ ‏نَهَانَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَسْتَقْبِلَ الْقِبْلَةَ ‏ ‏بِغَائِطٍ ‏ ‏أَوْ بَوْلٍ وَأَنْ لَا ‏ ‏نَسْتَنْجِيَ ‏ ‏بِالْيَمِينِ وَأَنْ لَا ‏ ‏يَسْتَنْجِيَ ‏ ‏أَحَدُنَا بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ أَوْ ‏ ‏نَسْتَنْجِيَ ‏ ‏بِرَجِيعٍ ‏ ‏أَوْ عَظْمٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('696eef5f-bc29-585d-b893-0f32ec5a6917', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '7', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ النُّفَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَنَا لَكُمْ بِمَنْزِلَةِ الْوَالِدِ أُعَلِّمُكُمْ فَإِذَا أَتَى أَحَدُكُمْ ‏ ‏الْغَائِطَ ‏ ‏فَلَا يَسْتَقْبِلْ الْقِبْلَةَ وَلَا يَسْتَدْبِرْهَا وَلَا ‏ ‏يَسْتَطِبْ ‏ ‏بِيَمِينِهِ وَكَانَ يَأْمُرُ بِثَلَاثَةِ أَحْجَارٍ ‏ ‏وَيَنْهَى عَنْ الرَّوْثِ ‏ ‏وَالرِّمَّةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fc64aa50-b69e-5451-a115-f9e8c3f13d52', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '8', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدُ بْنُ مُسَرْهَدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏رِوَايَةً ‏ ‏قَالَ ‏ ‏إِذَا أَتَيْتُمْ ‏ ‏الْغَائِطَ ‏ ‏فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ ‏ ‏بِغَائِطٍ ‏ ‏وَلَا بَوْلٍ وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا ‏ ‏فَقَدِمْنَا ‏ ‏الشَّامَ ‏ ‏فَوَجَدْنَا مَرَاحِيضَ قَدْ بُنِيَتْ قِبَلَ الْقِبْلَةِ فَكُنَّا نَنْحَرِفُ عَنْهَا وَنَسْتَغْفِرُ اللَّهَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e3715cf4-4807-5f67-bf31-6d4b0d6bdde6', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '9', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي زَيْدٍ ‏ ‏عَنْ ‏ ‏مَعْقِلِ بْنِ أَبِي مَعْقِلٍ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَسْتَقْبِلَ الْقِبْلَتَيْنِ بِبَوْلٍ أَوْ ‏ ‏غَائِطٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَأَبُو زَيْدٍ ‏ ‏هُوَ مَوْلَى ‏ ‏بَنِي ثَعْلَبَةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('106587b6-d28b-5931-bfeb-7286d7274578', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '10', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏مَرْوَانَ الْأَصْفَرِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَنَاخَ رَاحِلَتَهُ ‏ ‏مُسْتَقْبِلَ الْقِبْلَةِ ثُمَّ جَلَسَ يَبُولُ إِلَيْهَا فَقُلْتُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَلَيْسَ قَدْ نُهِيَ عَنْ هَذَا قَالَ بَلَى إِنَّمَا ‏ ‏نُهِيَ عَنْ ذَلِكَ فِي الْفَضَاءِ فَإِذَا كَانَ بَيْنَكَ وَبَيْنَ الْقِبْلَةِ شَيْءٌ يَسْتُرُكَ فَلَا بَأْسَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1727e4cd-3491-592f-b96a-f75acccde15f', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '11', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقَدْ ارْتَقَيْتُ عَلَى ظَهْرِ الْبَيْتِ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى لَبِنَتَيْنِ مُسْتَقْبِلَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏لِحَاجَتِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('181083fc-48f9-53f1-b2bd-7d104568cf19', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '12', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ إِسْحَقَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبَانَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِبَوْلٍ فَرَأَيْتُهُ قَبْلَ أَنْ يُقْبَضَ بِعَامٍ يَسْتَقْبِلُهَا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92579435-f53b-5c3c-a496-6ac52d420f3f', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '13', '‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَرَادَ حَاجَةً لَا يَرْفَعُ ثَوْبَهُ حَتَّى يَدْنُوَ مِنْ الْأَرْضِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏عَبْدُ السَّلَامِ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏وَهُوَ ضَعِيفٌ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى الرَّمْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ السَّلَامِ ‏ ‏بِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e5a71930-08c6-5202-9302-fa487b92c1b1', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '14', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ بْنِ مَيْسَرَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عِيَاضٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَخْرُجْ الرَّجُلَانِ يَضْرِبَانِ ‏ ‏الْغَائِطَ ‏ ‏كَاشِفَيْنِ عَنْ عَوْرَتِهِمَا يَتَحَدَّثَانِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَمْقُتُ عَلَى ذَلِكَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏هَذَا لَمْ يُسْنِدْهُ إِلَّا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e2d1195f-6abb-578a-8b2b-24b8daf3824c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '15', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏وَأَبُو بَكْرِ ‏ ‏ابْنَا ‏ ‏أَبِي شَيْبَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَرَّ رَجُلٌ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَرُوِيَ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَغَيْرِهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَيَمَّمَ ثُمَّ رَدَّ عَلَى الرَّجُلِ السَّلَامَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7419445d-cfea-5e22-9245-8144cc815f4c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '16', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏حُضَيْنِ بْنِ الْمُنْذِرِ أَبِي سَاسَانَ ‏ ‏عَنْ ‏ ‏الْمُهَاجِرِ بْنِ قُنْفُذٍ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ حَتَّى تَوَضَّأَ ثُمَّ اعْتَذَرَ إِلَيْهِ فَقَالَ ‏ ‏إِنِّي كَرِهْتُ أَنْ أَذْكُرَ اللَّهَ عَزَّ وَجَلَّ إِلَّا عَلَى طُهْرٍ ‏ ‏أَوْ قَالَ عَلَى طَهَارَةٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7ab54185-cbea-589c-8d18-ccc2ebbdad4f', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '17', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ سَلَمَةَ يَعْنِي الْفَأْفَاءَ ‏ ‏عَنْ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ اللَّهَ عَزَّ وَجَلَّ عَلَى كُلِّ أَحْيَانِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c20790a5-0813-5f76-80f1-4be262731f65', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '18', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْخَلَاءَ ‏ ‏وَضَعَ ‏ ‏خَاتَمَهُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏هَذَا ‏ ‏حَدِيثٌ مُنْكَرٌ ‏ ‏وَإِنَّمَا يُعْرَفُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخَذَ خَاتَمًا مِنْ ‏ ‏وَرِقٍ ‏ ‏ثُمَّ أَلْقَاهُ ‏ ‏وَالْوَهْمُ فِيهِ مِنْ ‏ ‏هَمَّامٍ ‏ ‏وَلَمْ يَرْوِهِ إِلَّا ‏ ‏هَمَّامٌ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c058a544-3b27-5b45-bc32-99e9988eff78', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '19', '‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَهَنَّادُ بْنُ السَّرِيِّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَبْرَيْنِ فَقَالَ ‏ ‏إِنَّهُمَا يُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ أَمَّا هَذَا فَكَانَ لَا ‏ ‏يَسْتَنْزِهُ ‏ ‏مِنْ الْبَوْلِ وَأَمَّا هَذَا فَكَانَ يَمْشِي ‏ ‏بِالنَّمِيمَةِ ‏ ‏ثُمَّ دَعَا ‏ ‏بِعَسِيبٍ ‏ ‏رَطْبٍ فَشَقَّهُ بِاثْنَيْنِ ثُمَّ غَرَسَ عَلَى هَذَا وَاحِدًا وَعَلَى هَذَا وَاحِدًا وَقَالَ لَعَلَّهُ يُخَفَّفُ عَنْهُمَا مَا لَمْ يَيْبَسَا ‏ ‏قَالَ ‏ ‏هَنَّادٌ ‏ ‏يَسْتَتِرُ مَكَانَ يَسْتَنْزِهُ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَعْنَاهُ قَالَ كَانَ لَا يَسْتَتِرُ مِنْ بَوْلِهِ وَقَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏يَسْتَنْزِهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5705be0e-1c7e-5615-b98b-0e325a088d03', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '20', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَسَنَةَ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ أَنَا ‏ ‏وَعَمْرُو بْنُ الْعَاصِ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ وَمَعَهُ ‏ ‏دَرَقَةٌ ‏ ‏ثُمَّ اسْتَتَرَ بِهَا ثُمَّ بَالَ فَقُلْنَا انْظُرُوا إِلَيْهِ يَبُولُ كَمَا تَبُولُ الْمَرْأَةُ فَسَمِعَ ذَلِكَ فَقَالَ ‏ ‏أَلَمْ تَعْلَمُوا مَا لَقِيَ صَاحِبُ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانُوا إِذَا أَصَابَهُمْ الْبَوْلُ قَطَعُوا مَا أَصَابَهُ الْبَوْلُ مِنْهُمْ فَنَهَاهُمْ فَعُذِّبَ فِي قَبْرِهِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏قَالَ ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏قَالَ ‏ ‏جِلْدِ أَحَدِهِمْ ‏ ‏و قَالَ ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَسَدِ أَحَدِهِمْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2390e6d1-35f0-5ddc-bbb7-c8d1ec483d74', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '21', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏وَمُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏وَهَذَا لَفْظُ ‏ ‏حَفْصٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبَاطَةَ ‏ ‏قَوْمٍ ‏ ‏فَبَالَ قَائِمًا ثُمَّ دَعَا بِمَاءٍ فَمَسَحَ عَلَى خُفَّيْهِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏قَالَ ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ ‏ ‏فَذَهَبْتُ أَتَبَاعَدُ فَدَعَانِي حَتَّى كُنْتُ عِنْدَ عَقِبِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5fe4b940-d9b2-5e2e-a850-21d461fab081', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '22', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏حُكَيْمَةَ بِنْتِ أُمَيْمَةَ بِنْتِ رُقَيْقَةَ ‏ ‏عَنْ ‏ ‏أُمِّهَا ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدَحٌ ‏ ‏مِنْ عِيدَانٍ تَحْتَ سَرِيرِهِ يَبُولُ فِيهِ بِاللَّيْلِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('18c1630d-4cf4-500b-b2ec-3eba298902b6', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '23', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اتَّقُوا اللَّاعِنَيْنِ قَالُوا وَمَا اللَّاعِنَانِ يَا رَسُولَ اللَّهِ قَالَ الَّذِي ‏ ‏يَتَخَلَّى ‏ ‏فِي طَرِيقِ النَّاسِ أَوْ ظِلِّهِمْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5aadcd38-7d35-53da-90f3-1992befefb80', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '24', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ سُوَيْدٍ الرَّمْلِيُّ ‏ ‏وَعُمَرُ بْنُ الْخَطَّابِ أَبُو حَفْصٍ ‏ ‏وَحَدِيثُهُ أَتَمُّ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْحَكَمِ ‏ ‏حَدَّثَهُمْ قَالَ أَخْبَرَنَا ‏ ‏نَافِعُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنِي ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْحِمْيَرِيَّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏مُعَاذِ بْنِ جَبَلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا الْمَلَاعِنَ الثَّلَاثَةَ الْبَرَازَ فِي ‏ ‏الْمَوَارِدِ ‏ ‏وَقَارِعَةِ الطَّرِيقِ ‏ ‏وَالظِّلِّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a7cc54dc-2906-54ef-932d-d69eeda39951', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '25', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏وَالْحَسَنُ بْنُ عَلِيٍّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏أَحْمَدُ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏أَشْعَثُ ‏ ‏وَقَالَ ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي مُسْتَحَمِّهِ ثُمَّ يَغْتَسِلُ فِيهِ ‏ ‏قَالَ ‏ ‏أَحْمَدُ ‏ ‏ثُمَّ يَتَوَضَّأُ فِيهِ ‏ ‏فَإِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9dc1c89d-30f5-5416-b677-cd19e07a8f0a', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '26', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْحِمْيَرِيِّ وَهُوَ ابْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏رَجُلًا ‏ ‏صَحِبَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا صَحِبَهُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَمْتَشِطَ أَحَدُنَا كُلَّ يَوْمٍ أَوْ يَبُولَ فِي مُغْتَسَلِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3e2b845a-93e6-51c1-916f-dc2466b7fa29', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '27', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ بْنِ مَيْسَرَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَرْجِسَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُبَالَ فِي الْجُحْرِ ‏ ‏قَالُوا ‏ ‏لِقَتَادَةَ ‏ ‏مَا يُكْرَهُ مِنْ الْبَوْلِ فِي الْجُحْرِ قَالَ كَانَ يُقَالُ إِنَّهَا مَسَاكِنُ الْجِنِّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4998d12b-ba06-540e-9d18-093d34a4e147', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '28', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ مِنْ ‏ ‏الْغَائِطِ ‏ ‏قَالَ غُفْرَانَكَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('58433ad3-0cd8-5560-8ae5-371d80e20307', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '29', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏وَمُوسَى بْنُ إِسْمَعِيلَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَالَ أَحَدُكُمْ فَلَا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَإِذَا أَتَى الْخَلَاءَ فَلَا يَتَمَسَّحْ بِيَمِينِهِ وَإِذَا شَرِبَ فَلَا يَشْرَبْ نَفَسًا وَاحِدًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('29702cf4-1abf-5ff5-90c9-2fc64f74cbbe', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '30', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ آدَمَ بْنِ سُلَيْمَانَ الْمِصِّيصِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو أَيُّوبَ يَعْنِي الْإِفْرِيقِيَّ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏وَمَعْبَدٍ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ وَهْبٍ الْخُزَاعِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏حَفْصَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَجْعَلُ يَمِينَهُ لِطَعَامِهِ وَشَرَابِهِ وَثِيَابِهِ وَيَجْعَلُ شِمَالَهُ لِمَا سِوَى ذَلِكَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6ca1859d-4f72-50de-9759-063702a70d45', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '31', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو تَوْبَةَ الرَّبِيعُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنِي ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ يَدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْيُمْنَى لِطُهُورِهِ وَطَعَامِهِ وَكَانَتْ يَدُهُ الْيُسْرَى ‏ ‏لِخَلَائِهِ ‏ ‏وَمَا كَانَ مِنْ أَذًى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَاتِمِ بْنِ بُزَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَعْنَاهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('406154c6-5e6f-5501-bdf2-3d3c4e901444', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '32', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى الرَّازِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏الْحُصَيْنِ الْحُبْرَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اكْتَحَلَ فَلْيُوتِرْ مَنْ فَعَلَ فَقْدَ أَحْسَنَ وَمَنْ لَا فَلَا ‏ ‏حَرَجَ ‏ ‏وَمَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا ‏ ‏حَرَجَ ‏ ‏وَمَنْ أَكَلَ فَمَا ‏ ‏تَخَلَّلَ ‏ ‏فَلْيَلْفِظْ ‏ ‏وَمَا لَاكَ بِلِسَانِهِ فَلْيَبْتَلِعْ مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا ‏ ‏حَرَجَ ‏ ‏وَمَنْ أَتَى ‏ ‏الْغَائِطَ ‏ ‏فَلْيَسْتَتِرْ فَإِنْ لَمْ يَجِدْ إِلَّا أَنْ يَجْمَعَ ‏ ‏كَثِيبًا ‏ ‏مِنْ رَمْلٍ فَلْيَسْتَدْبِرْهُ فَإِنَّ الشَّيْطَانَ يَلْعَبُ بِمَقَاعِدِ بَنِي ‏ ‏آدَمَ ‏ ‏مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا ‏ ‏حَرَجَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏قَالَ ‏ ‏حُصَيْنٌ الْحِمْيَرِيُّ ‏ ‏وَرَوَاهُ ‏ ‏عَبْدُ الْمَلِكِ بْنُ الصَّبَّاحِ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخَيْرُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏أَبُو سَعِيدٍ الْخَيْرُ ‏ ‏هُوَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ff3089e1-f13f-50dd-8a0b-544c6c8394e4', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '33', '‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ خَالِدِ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ الْهَمْدَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ يَعْنِي ابْنَ فَضَالَةَ الْمِصْرِيَّ ‏ ‏عَنْ ‏ ‏عَيَّاشِ بْنِ عَبَّاسٍ الْقِتْبَانِيِّ ‏ ‏أَنَّ ‏ ‏شِيَيْمَ بْنَ بَيْتَانَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏شَيْبَانَ الْقِتْبَانِيِّ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏مَسْلَمَةَ بْنَ مُخَلَّدٍ ‏ ‏اسْتَعْمَلَ ‏ ‏رُوَيْفِعَ بْنَ ثَابِتٍ ‏ ‏عَلَى أَسْفَلِ الْأَرْضِ قَالَ ‏ ‏شَيْبَانُ ‏ ‏فَسِرْنَا مَعَهُ مِنْ ‏ ‏كَوْمِ شَرِيكٍ ‏ ‏إِلَى ‏ ‏عَلْقَمَاءَ ‏ ‏أَوْ مِنْ ‏ ‏عَلْقَمَاءَ ‏ ‏إِلَى ‏ ‏كَوْمِ شَرِيكٍ ‏ ‏يُرِيدُ ‏ ‏عَلْقَامَ ‏ ‏فَقَالَ ‏ ‏رُوَيْفِعٌ ‏ ‏إِنْ كَانَ أَحَدُنَا فِي زَمَنِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَأْخُذُ ‏ ‏نِضْوَ ‏ ‏أَخِيهِ عَلَى أَنَّ لَهُ النِّصْفَ مِمَّا يَغْنَمُ وَلَنَا النِّصْفُ وَإِنْ كَانَ أَحَدُنَا لَيَطِيرُ لَهُ ‏ ‏النَّصْلُ ‏ ‏وَالرِّيشُ ‏ ‏وَلِلْآخَرِ ‏ ‏الْقِدْحُ ‏ ‏ثُمَّ قَالَ قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏رُوَيْفِعُ ‏ ‏لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ بَعْدِي فَأَخْبِرْ النَّاسَ أَنَّهُ ‏ ‏مَنْ عَقَدَ لِحْيَتَهُ أَوْ ‏ ‏تَقَلَّدَ ‏ ‏وَتَرًا ‏ ‏أَوْ اسْتَنْجَى ‏ ‏بِرَجِيعِ ‏ ‏دَابَّةٍ أَوْ عَظْمٍ فَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُ بَرِيءٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُفَضَّلٌ ‏ ‏عَنْ ‏ ‏عَيَّاشٍ ‏ ‏أَنَّ ‏ ‏شِيَيْمَ بْنَ بَيْتَانَ ‏ ‏أَخْبَرَهُ ‏ ‏بِهَذَا الْحَدِيثِ أَيْضًا ‏ ‏عَنْ ‏ ‏أَبِي سَالِمٍ الْجَيْشَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏يَذْكُرُ ذَلِكَ وَهُوَ مَعَهُ ‏ ‏مُرَابِطٌ ‏ ‏بِحِصْنِ ‏ ‏بَابِ أَلْيُونَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏حِصْنُ ‏ ‏أَلْيُونَ ‏ ‏بِالْفِسْطَاطِ ‏ ‏عَلَى جَبَلٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَهُوَ ‏ ‏شَيْبَانُ بْنُ أُمَيَّةَ ‏ ‏يُكْنَى ‏ ‏أَبَا حُذَيْفَةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b3a4ed0e-6fc7-56a8-a640-a34c48f4349b', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '34', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَتَمَسَّحَ بِعَظْمٍ أَوْ بَعْرٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('16713b1d-7b83-5df9-9759-aed40276475f', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '35', '‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ الْحِمْصِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي عَمْرٍو السَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الدَّيْلَمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَدِمَ وَفْدُ الْجِنِّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا ‏ ‏مُحَمَّدُ ‏ ‏انْهَ أُمَّتَكَ أَنْ ‏ ‏يَسْتَنْجُوا ‏ ‏بِعَظْمٍ أَوْ رَوْثَةٍ أَوْ حُمَمَةٍ فَإِنَّ اللَّهَ تَعَالَى جَعَلَ لَنَا فِيهَا رِزْقًا قَالَ فَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('de31093d-834f-5b11-9492-7983875917e9', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '36', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ قُرْطٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ذَهَبَ أَحَدُكُمْ إِلَى ‏ ‏الْغَائِطِ ‏ ‏فَلْيَذْهَبْ مَعَهُ بِثَلَاثَةِ أَحْجَارٍ ‏ ‏يَسْتَطِيبُ ‏ ‏بِهِنَّ فَإِنَّهَا ‏ ‏تُجْزِئُ عَنْهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b6466a0-b607-52e3-aad5-578c166437d0', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '37', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ النُّفَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خُزَيْمَةَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ خُزَيْمَةَ ‏ ‏عَنْ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الِاسْتِطَابَةِ ‏ ‏فَقَالَ ‏ ‏بِثَلَاثَةِ أَحْجَارٍ لَيْسَ فِيهَا ‏ ‏رَجِيعٌ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏كَذَا ‏ ‏رَوَاهُ ‏ ‏أَبُو أُسَامَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ يَعْنِي ابْنَ عُرْوَةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0f95f767-451b-51b4-bf44-f68d6c995dee', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '38', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَخَلَفُ بْنُ هِشَامٍ الْمُقْرِئُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَحْيَى التَّوْأَمُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو يَعْقُوبَ التَّوْأَمُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏بَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ ‏ ‏عُمَرُ ‏ ‏خَلْفَهُ بِكُوزٍ مِنْ مَاءٍ فَقَالَ مَا هَذَا يَا ‏ ‏عُمَرُ ‏ ‏فَقَالَ هَذَا مَاءٌ تَتَوَضَّأُ بِهِ قَالَ ‏ ‏مَا أُمِرْتُ كُلَّمَا بُلْتُ أَنْ أَتَوَضَّأَ وَلَوْ فَعَلْتُ لَكَانَتْ سُنَّةً ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('730c93b1-9d68-5c1a-954d-d8135c0bae39', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '39', '‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ بَقِيَّةَ ‏ ‏عَنْ ‏ ‏خَالِدٍ يَعْنِي الْوَاسِطِيَّ ‏ ‏عَنْ ‏ ‏خَالِدٍ يَعْنِي الْحَذَّاءَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏حَائِطًا ‏ ‏وَمَعَهُ ‏ ‏غُلَامٌ ‏ ‏مَعَهُ ‏ ‏مِيضَأَةٌ ‏ ‏وَهُوَ أَصْغَرُنَا فَوَضَعَهَا عِنْدَ السِّدْرَةِ فَقَضَى حَاجَتَهُ فَخَرَجَ عَلَيْنَا وَقَدْ ‏ ‏اسْتَنْجَى ‏ ‏بِالْمَاءِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92120d35-14bd-5e51-add8-ffc094f4028f', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '40', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَزَلَتْ هَذِهِ الْآيَةُ فِي أَهْلِ ‏ ‏قُبَاءٍ ‏ { ‏فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا ‏} ‏قَالَ كَانُوا ‏ ‏يَسْتَنْجُونَ ‏ ‏بِالْمَاءِ فَنَزَلَتْ فِيهِمْ هَذِهِ الْآيَةُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c7e18a2f-177b-5140-b4dc-70eb856d29d9', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '41', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏وَهَذَا لَفْظُهُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ يَعْنِي الْمُخَرَّمِيَّ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى الْخَلَاءَ أَتَيْتُهُ بِمَاءٍ فِي ‏ ‏تَوْرٍ ‏ ‏أَوْ ‏ ‏رَكْوَةٍ ‏ ‏فَاسْتَنْجَى ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏فِي حَدِيثِ ‏ ‏وَكِيعٍ ‏ ‏ثُمَّ مَسَحَ يَدَهُ عَلَى الْأَرْضِ ثُمَّ أَتَيْتُهُ بِإِنَاءٍ آخَرَ فَتَوَضَّأَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَحَدِيثُ ‏ ‏الْأَسْوَدِ بْنِ عَامِرٍ ‏ ‏أَتَمُّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('975158c1-92f9-5090-a371-0dc21e790c84', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '42', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَرْفَعُهُ قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى الْمُؤْمِنِينَ لَأَمَرْتُهُمْ بِتَأْخِيرِ الْعِشَاءِ وَبِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0cf41581-0e48-53e0-a8b6-74f4a48dc634', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '43', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏فَرَأَيْتُ ‏ ‏زَيْدًا ‏ ‏يَجْلِسُ فِي الْمَسْجِدِ وَإِنَّ السِّوَاكَ مِنْ أُذُنِهِ مَوْضِعَ الْقَلَمِ مِنْ أُذُنِ الْكَاتِبِ فَكُلَّمَا قَامَ إِلَى الصَّلَاةِ اسْتَاكَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af63dbe7-4f82-5354-b5cc-b7e28b3ef2b4', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '44', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَوْفٍ الطَّائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قُلْتُ أَرَأَيْتَ تَوَضُّؤَ ‏ ‏ابْنِ عُمَرَ ‏ ‏لِكُلِّ صَلَاةٍ طَاهِرًا وَغَيْرَ طَاهِرٍ عَمَّ ذَاكَ فَقَالَ ‏ ‏حَدَّثَتْنِيهِ ‏ ‏أَسْمَاءُ بِنْتُ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ حَنْظَلَةَ بْنِ أَبِي عَامِرٍ ‏ ‏حَدَّثَهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرَ بِالْوُضُوءِ لِكُلِّ صَلَاةٍ طَاهِرًا وَغَيْرَ طَاهِرٍ فَلَمَّا شَقَّ ذَلِكَ عَلَيْهِ أُمِرَ بِالسِّوَاكِ لِكُلِّ صَلَاةٍ ‏ ‏فَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَرَى أَنَّ بِهِ قُوَّةً فَكَانَ لَا يَدَعُ الْوُضُوءَ لِكُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏رَوَاهُ عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9b5fe41b-ee4c-5ad3-86a8-a788c2dfe294', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '45', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏وَسُلَيْمَانُ بْنُ دَاوُدَ الْعَتَكِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ ‏ ‏أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَسْتَحْمِلُهُ ‏ ‏فَرَأَيْتُهُ يَسْتَاكُ عَلَى لِسَانِهِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَقَالَ ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَسْتَاكُ وَقَدْ وَضَعَ السِّوَاكَ عَلَى طَرَفِ لِسَانِهِ ‏ ‏وَهُوَ يَقُولُ ‏ ‏إِهْ ‏ ‏إِهْ ‏ ‏يَعْنِي ‏ ‏يَتَهَوَّعُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏قَالَ ‏ ‏مُسَدَّدٌ ‏ ‏فَكَانَ حَدِيثًا طَوِيلًا وَلَكِنِّي اخْتَصَرْتُهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ce4d381-a2ff-57ff-9883-21223fe7cf1d', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '46', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَنْبَسَةُ بْنُ عَبْدِ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَنُّ ‏ ‏وَعِنْدَهُ رَجُلَانِ أَحَدُهُمَا أَكْبَرُ مِنْ الْآخَرِ فَأَوْحَى اللَّهُ إِلَيْهِ فِي فَضْلِ السِّوَاكِ أَنْ كَبِّرْ أَعْطِ السِّوَاكَ أَكْبَرَهُمَا ‏ ‏قَالَ ‏ ‏أَحْمَدُ ‏ ‏هُوَ ‏ ‏ابْنُ حَزْمٍ ‏ ‏قَالَ لَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏هُوَ ‏ ‏ابْنُ الْأَعْرَابِيِّ ‏ ‏هَذَا مِمَّا تَفَرَّدَ بِهِ أَهْلُ ‏ ‏الْمَدِينَةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa71a92c-2978-587f-8855-a4b95ca854c1', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '47', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى الرَّازِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏بِأَيِّ شَيْءٍ كَانَ يَبْدَأُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ بَيْتَهُ قَالَتْ بِالسِّوَاكِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('980cb86f-d618-5f68-98d0-718512ea43b8', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '48', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَنْبَسَةُ بْنُ سَعِيدٍ الْكُوفِيُّ الْحَاسِبُ ‏ ‏حَدَّثَنِي ‏ ‏كَثِيرٌ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَاكُ ‏ ‏فَيُعْطِينِي السِّوَاكَ لِأَغْسِلَهُ فَأَبْدَأُ بِهِ فَأَسْتَاكُ ثُمَّ أَغْسِلُهُ وَأَدْفَعُهُ إِلَيْهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4960bb6e-1033-50b0-9708-dc56e75ebf9b', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '49', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرٌ مِنْ الْفِطْرَةِ قَصُّ الشَّارِبِ وَإِعْفَاءُ اللِّحْيَةِ وَالسِّوَاكُ ‏ ‏وَالِاسْتِنْشَاقُ بِالْمَاءِ وَقَصُّ الْأَظْفَارِ وَغَسْلُ ‏ ‏الْبَرَاجِمِ ‏ ‏وَنَتْفُ الْإِبِطِ وَحَلْقُ ‏ ‏الْعَانَةِ ‏ ‏وَانْتِقَاصُ الْمَاءِ ‏ ‏يَعْنِي ‏ ‏الِاسْتِنْجَاءَ ‏ ‏بِالْمَاءِ ‏ ‏قَالَ ‏ ‏زَكَرِيَّا ‏ ‏قَالَ ‏ ‏مُصْعَبٌ ‏ ‏وَنَسِيتُ الْعَاشِرَةَ إِلَّا أَنْ تَكُونَ الْمَضْمَضَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏وَدَاوُدُ بْنُ شَبِيبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارِ بْنِ يَاسِرٍ ‏ ‏قَالَ ‏ ‏مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏و قَالَ ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ الْفِطْرَةِ الْمَضْمَضَةَ ‏ ‏وَالِاسْتِنْشَاقَ فَذَكَرَ نَحْوَهُ وَلَمْ يَذْكُرْ إِعْفَاءَ اللِّحْيَةِ وَزَادَ ‏ ‏وَالْخِتَانَ ‏ ‏قَالَ ‏ ‏وَالِانْتِضَاحَ ‏ ‏وَلَمْ يَذْكُرْ انْتِقَاصَ الْمَاءِ ‏ ‏يَعْنِي ‏ ‏الِاسْتِنْجَاءَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَرُوِيَ ‏ ‏نَحْوُهُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَقَالَ ‏ ‏خَمْسٌ كُلُّهَا فِي الرَّأْسِ وَذَكَرَ فِيهَا الْفَرْقَ وَلَمْ يَذْكُرْ إِعْفَاءَ اللِّحْيَةِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَرُوِيَ ‏ ‏نَحْوُ حَدِيثِ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏وَمُجَاهِدٍ ‏ ‏وَعَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏قَوْلُهُمْ وَلَمْ يَذْكُرُوا إِعْفَاءَ اللِّحْيَةِ ‏ ‏وَفِي حَدِيثِ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ ‏ ‏وَإِعْفَاءُ اللِّحْيَةِ ‏ ‏وَعَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏نَحْوُهُ وَذَكَرَ إِعْفَاءَ اللِّحْيَةِ ‏ ‏وَالْخِتَانَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7b339342-1a42-5624-ac59-b8b7899c993c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '50', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَحُصَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا قَامَ مِنْ اللَّيْلِ ‏ ‏يَشُوصُ ‏ ‏فَاهُ بِالسِّوَاكِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('74169032-1765-506c-a792-19169b124b21', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '51', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏بَهْزُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُوضَعُ لَهُ وَضُوءُهُ وَسِوَاكُهُ فَإِذَا قَامَ مِنْ اللَّيْلِ ‏ ‏تَخَلَّى ‏ ‏ثُمَّ اسْتَاكَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7fdeaeeb-2bd3-5294-899a-0bba8d60622d', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '52', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَرْقُدُ مِنْ لَيْلٍ وَلَا نَهَارٍ فَيَسْتَيْقِظُ إِلَّا تَسَوَّكَ قَبْلَ أَنْ يَتَوَضَّأَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('858d2651-1b1c-59a3-b633-9090e9dd6959', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '53', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيِّ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بِتُّ لَيْلَةً عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا اسْتَيْقَظَ مِنْ مَنَامِهِ أَتَى طَهُورَهُ فَأَخَذَ سِوَاكَهُ فَاسْتَاكَ ثُمَّ تَلَا هَذِهِ الْآيَاتِ ‏ { ‏إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي ‏ ‏الْأَلْبَابِ ‏} ‏حَتَّى قَارَبَ أَنْ يَخْتِمَ السُّورَةَ ‏ ‏أَوْ خَتَمَهَا ‏ ‏ثُمَّ تَوَضَّأَ فَأَتَى مُصَلَّاهُ فَصَلَّى رَكْعَتَيْنِ ثُمَّ رَجَعَ إِلَى فِرَاشِهِ فَنَامَ مَا شَاءَ اللَّهُ ثُمَّ اسْتَيْقَظَ فَفَعَلَ مِثْلَ ذَلِكَ ثُمَّ رَجَعَ إِلَى فِرَاشِهِ فَنَامَ ثُمَّ اسْتَيْقَظَ فَفَعَلَ مِثْلَ ذَلِكَ ثُمَّ رَجَعَ إِلَى فِرَاشِهِ فَنَامَ ثُمَّ اسْتَيْقَظَ فَفَعَلَ مِثْل ذَلِكَ كُلُّ ذَلِكَ يَسْتَاكُ وَيُصَلِّي رَكْعَتَيْنِ ثُمَّ أَوْتَرَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏قَالَ ‏ ‏فَتَسَوَّكَ وَتَوَضَّأَ وَهُوَ يَقُولُ ‏ { ‏إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالْأَرْضِ ‏} ‏حَتَّى خَتَمَ السُّورَةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b7fd3e2b-acd4-5813-81f1-7ca7473b1504', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '54', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقْبَلُ اللَّهُ عَزَّ وَجَلَّ صَدَقَةً مِنْ ‏ ‏غُلُولٍ ‏ ‏وَلَا صَلَاةً بِغَيْرِ طُهُورٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c4afa288-efc4-5e36-b073-692ecf80a671', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '55', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْبَلُ اللَّهُ صَلَاةَ أَحَدِكُمْ إِذَا ‏ ‏أَحْدَثَ ‏ ‏حَتَّى يَتَوَضَّأَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('30efdfc0-a443-53d8-afd2-140d238e5653', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '56', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِفْتَاحُ الصَّلَاةِ الطُّهُورُ ‏ ‏وَتَحْرِيمُهَا ‏ ‏التَّكْبِيرُ وَتَحْلِيلُهَا التَّسْلِيمُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9dba0354-a87b-5964-b3ba-a9beadd43fde', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '57', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ الْمُقْرِئُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ زِيَادٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَأَنَا لِحَدِيثِ ‏ ‏ابْنِ يَحْيَى ‏ ‏أَتْقَنُ ‏ ‏عَنْ ‏ ‏غُطَيْفٍ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي غُطَيْفٍ الْهُذَلِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَلَمَّا نُودِيَ بِالظُّهْرِ تَوَضَّأَ فَصَلَّى فَلَمَّا نُودِيَ بِالْعَصْرِ تَوَضَّأَ فَقُلْتُ لَهُ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ عَلَى طُهْرٍ كَتَبَ اللَّهُ لَهُ عَشْرَ حَسَنَاتٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَهَذَا حَدِيثُ ‏ ‏مُسَدَّدٍ ‏ ‏وَهُوَ أَتَمُّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ff6c12b9-2437-5011-b07e-2aa7258d653b', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '58', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَعُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏وَالْحَسَنُ بْنُ عَلِيٍّ ‏ ‏وَغَيْرُهُمْ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمَاءِ وَمَا ‏ ‏يَنُوبُهُ ‏ ‏مِنْ الدَّوَابِّ وَالسِّبَاعِ فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ لَمْ يَحْمِلْ ‏ ‏الْخَبَثَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَهَذَا لَفْظُ ‏ ‏ابْنُ الْعَلَاءِ ‏ ‏و قَالَ ‏ ‏عُثْمَانُ ‏ ‏وَالْحَسَنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَهُوَ الصَّوَابُ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الْمَاءِ يَكُونُ فِي الْفَلَاةِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0eb69295-6722-542d-b285-4767f785f7e8', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '59', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ فَإِنَّهُ لَا يَنْجُسُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏وَقَفَهُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8d941933-bdfc-5d40-b8ed-f7a851f73064', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '60', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَالْحَسَنُ بْنُ عَلِيٍّ ‏ ‏وَمُحَمَّدُ بْنُ سُلَيْمَانَ الْأَنْبَارِيُّ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ قِيلَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَتَوَضَّأُ مِنْ ‏ ‏بِئْرِ بُضَاعَةَ ‏ ‏وَهِيَ بِئْرٌ يُطْرَحُ فِيهَا الْحِيَضُ وَلَحْمُ الْكِلَابِ وَالنَّتْنُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَاءُ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَقَالَ بَعْضُهُمْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ رَافِعٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6ecc2b7c-1007-5170-8403-3949631da106', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '61', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ أَبِي شُعَيْبٍ ‏ ‏وَعَبْدُ الْعَزِيزِ بْنُ يَحْيَى الْحَرَّانِيَّانِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏سَلِيطِ بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ رَافِعٍ الْأَنْصَارِيِّ ثُمَّ الْعَدَوِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُقَالُ لَهُ إِنَّهُ ‏ ‏يُسْتَقَى لَكَ مِنْ ‏ ‏بِئْرِ بُضَاعَةَ ‏ ‏وَهِيَ بِئْرٌ يُلْقَى فِيهَا لُحُومُ الْكِلَابِ ‏ ‏وَالْمَحَايِضُ ‏ ‏وَعَذِرُ النَّاسِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمَاءَ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏و سَمِعْت ‏ ‏قُتَيْبَةَ بْنَ سَعِيدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ قَيِّمَ ‏ ‏بِئْرِ بُضَاعَةَ ‏ ‏عَنْ عُمْقِهَا قَالَ أَكْثَرُ مَا يَكُونُ فِيهَا الْمَاءُ إِلَى ‏ ‏الْعَانَةِ ‏ ‏قُلْتُ فَإِذَا نَقَصَ قَالَ دُونَ الْعَوْرَةِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَقَدَّرْتُ أَنَا ‏ ‏بِئْرَ بُضَاعَةَ ‏ ‏بِرِدَائِي مَدَدْتُهُ عَلَيْهَا ثُمَّ ذَرَعْتُهُ فَإِذَا عَرْضُهَا سِتَّةُ أَذْرُعٍ وَسَأَلْتُ الَّذِي فَتَحَ لِي بَابَ الْبُسْتَانِ فَأَدْخَلَنِي إِلَيْهِ هَلْ غُيِّرَ بِنَاؤُهَا عَمَّا كَانَتْ عَلَيْهِ قَالَ لَا وَرَأَيْتُ فِيهَا مَاءً مُتَغَيِّرَ اللَّوْنِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dd0099ba-ec54-56cc-b27b-13b20cb697ae', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '62', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏اغْتَسَلَ بَعْضُ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏جَفْنَةٍ ‏ ‏فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَتَوَضَّأَ مِنْهَا ‏ ‏أَوْ يَغْتَسِلَ ‏ ‏فَقَالَتْ لَهُ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ جُنُبًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمَاءَ لَا يُجْنِبُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cb1ecdb6-6b52-52d8-8a6f-0eb667b17ec7', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '63', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏فِي حَدِيثِ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَغْتَسِلُ مِنْهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0569f7fa-73f8-5502-b046-58774886bbd9', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '64', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏وَلَا يَغْتَسِلُ فِيهِ مِنْ الْجَنَابَةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cc0217f3-077f-5488-af70-c656f45709ea', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '65', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏فِي حَدِيثِ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏طُهُورُ إِنَاءِ أَحَدِكُمْ إِذَا ‏ ‏وَلَغَ ‏ ‏فِيهِ الْكَلْبُ أَنْ يُغْسَلَ سَبْعَ مِرَارٍ أُولَاهُنَّ بِتُرَابٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَكَذَلِكَ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏وَحَبِيبُ بْنُ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏ح ‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ يَعْنِي ابْنَ سُلَيْمَانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِمَعْنَاهُ وَلَمْ يَرْفَعَاهُ ‏ ‏وَزَادَ وَإِذَا ‏ ‏وَلَغَ ‏ ‏الْهِرُّ غُسِلَ مَرَّةً ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('95195792-e87b-55b7-8808-fe585e87f739', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '66', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ سِيرِينَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي الْإِنَاءِ فَاغْسِلُوهُ سَبْعَ مَرَّاتٍ السَّابِعَةُ بِالتُّرَابِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَأَمَّا ‏ ‏أَبُو صَالِحٍ ‏ ‏وَأَبُو رَزِينٍ ‏ ‏وَالْأَعْرَجُ ‏ ‏وَثَابِتٌ الْأَحْنَفُ ‏ ‏وَهَمَّامُ بْنُ مُنَبِّهٍ ‏ ‏وَأَبُو السُّدِّيِّ عَبْدُ الرَّحْمَنِ ‏ ‏رَوَوْهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَلَمْ يَذْكُرُوا التُّرَابَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2ecd6a95-8499-5530-a6ae-220f9e1e101d', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '67', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏ابْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ الْكِلَابِ ثُمَّ قَالَ مَا لَهُمْ وَلَهَا فَرَخَّصَ فِي كَلْبِ الصَّيْدِ وَفِي كَلْبِ الْغَنَمِ وَقَالَ إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي الْإِنَاءِ فَاغْسِلُوهُ سَبْعَ مِرَارٍ وَالثَّامِنَةُ ‏ ‏عَفِّرُوهُ ‏ ‏بِالتُّرَابِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَهَكَذَا قَالَ ‏ ‏ابْنُ مُغَفَّلٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bc572982-5b4c-51c0-a651-321e6308d08d', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '68', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ الْقَعْنَبِيُّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدَةَ بِنْتِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏كَبْشَةَ بِنْتِ كَعْبِ بْنِ مَالِكٍ ‏ ‏وَكَانَتْ تَحْتَ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏دَخَلَ فَسَكَبَتْ لَهُ وَضُوءًا فَجَاءَتْ هِرَّةٌ فَشَرِبَتْ مِنْهُ ‏ ‏فَأَصْغَى ‏ ‏لَهَا الْإِنَاءَ حَتَّى شَرِبَتْ قَالَتْ ‏ ‏كَبْشَةُ ‏ ‏فَرَآنِي أَنْظُرُ إِلَيْهِ فَقَالَ أَتَعْجَبِينَ يَا ابْنَةَ أَخِي فَقُلْتُ نَعَمْ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّهَا مِنْ ‏ ‏الطَّوَّافِينَ ‏ ‏عَلَيْكُمْ ‏ ‏وَالطَّوَّافَاتِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5992e26c-d8a4-5e75-9155-fe3c92b20858', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '69', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ صَالِحِ بْنِ دِينَارٍ التَّمَّارِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَنَّ مَوْلَاتَهَا أَرْسَلَتْهَا بِهَرِيسَةٍ إِلَى ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَوَجَدَتْهَا تُصَلِّي فَأَشَارَتْ إِلَيَّ أَنْ ضَعِيهَا فَجَاءَتْ هِرَّةٌ فَأَكَلَتْ مِنْهَا فَلَمَّا انْصَرَفَتْ أَكَلَتْ مِنْ حَيْثُ أَكَلَتْ الْهِرَّةُ فَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّمَا هِيَ مِنْ ‏ ‏الطَّوَّافِينَ ‏ ‏عَلَيْكُمْ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِفَضْلِهَا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b0a30ec8-d9b4-5bdd-8d52-83e4da71a06a', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '70', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَنَحْنُ جُنُبَانِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c23757f4-8d12-500f-bf88-8049985d5439', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '71', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ النُّفَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ خَرَّبُوذَ ‏ ‏عَنْ ‏ ‏أُمِّ صُبَيَّةَ الْجُهَنِيَّةِ ‏ ‏قَالَتْ ‏ ‏اخْتَلَفَتْ ‏ ‏يَدِي وَيَدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْوُضُوءِ مِنْ إِنَاءٍ وَاحِدٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11450bf5-5f9a-550a-a36b-d2c45e0ba37c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '72', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ الرِّجَالُ وَالنِّسَاءُ يَتَوَضَّئُونَ فِي زَمَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مُسَدَّدٌ ‏ ‏مِنْ الْإِنَاءِ الْوَاحِدِ جَمِيعًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b3af4fab-3fbd-5596-9cfa-55c7abc1bc45', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '73', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا نَتَوَضَّأُ نَحْنُ وَالنِّسَاءُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏ ‏نُدْلِي ‏ ‏فِيهِ أَيْدِيَنَا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d5e1ea4a-a847-54cc-8324-60008a5884a9', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '74', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَبْدِ اللَّهِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْحِمْيَرِيِّ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏رَجُلًا ‏ ‏صَحِبَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَ سِنِينَ كَمَا صَحِبَهُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تَغْتَسِلَ الْمَرْأَةُ ‏ ‏بِفَضْلِ الرَّجُلِ ‏ ‏أَوْ يَغْتَسِلَ الرَّجُلُ ‏ ‏بِفَضْلِ الْمَرْأَةِ ‏ ‏زَادَ ‏ ‏مُسَدَّدٌ ‏ ‏وَلْيَغْتَرِفَا جَمِيعًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('edc16e3e-c0d1-5afc-9387-1d616af2c58c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '75', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ يَعْنِي الطَّيَالِسِيَّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي حَاجِبٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ بْنِ عَمْرٍو وَهُوَ الْأَقْرَعُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَتَوَضَّأَ الرَّجُلُ ‏ ‏بِفَضْلِ ‏ ‏طَهُورِ الْمَرْأَةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5f842920-219b-590c-874a-4da5b52c1b18', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '76', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَلَمَةَ ‏ ‏مِنْ آلِ ‏ ‏ابْنِ الْأَزْرَقِ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ أَبِي بُرْدَةَ ‏ ‏وَهُوَ مِنْ ‏ ‏بَنِي عَبْدِ الدَّارِ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنْ الْمَاءِ فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ بِمَاءِ الْبَحْرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c10da1cb-cec4-5cd1-8a90-926ab8ebb474', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '77', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏وَسُلَيْمَانُ بْنُ دَاوُدَ الْعَتَكِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ لَيْلَةَ الْجِنِّ ‏ ‏مَا فِي ‏ ‏إِدَاوَتِكَ ‏ ‏قَالَ نَبِيذٌ قَالَ تَمْرَةٌ طَيِّبَةٌ وَمَاءٌ طَهُورٌ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏و قَالَ ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي زَيْدٍ ‏ ‏أَوْ ‏ ‏زَيْدٍ ‏ ‏كَذَا قَالَ ‏ ‏شَرِيكٌ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏هَنَّادٌ ‏ ‏لَيْلَةَ الْجِنِّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('366114cf-1d90-5560-9829-2db6f575055d', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '78', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏مَنْ كَانَ مِنْكُمْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْجِنِّ فَقَالَ مَا كَانَ مَعَهُ مِنَّا أَحَدٌ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e685fdd8-3749-5e44-98f8-55bc722d87a3', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '79', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏أَنَّهُ ‏ ‏كَرِهَ الْوُضُوءَ بِاللَّبَنِ وَالنَّبِيذِ وَقَالَ إِنَّ التَّيَمُّمَ ‏ ‏أَعْجَبُ ‏ ‏إِلَيَّ مِنْهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('12186b73-039c-5c37-8e7c-391e2ef0fa6e', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '80', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَلْدَةَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَبَا الْعَالِيَةِ ‏ ‏عَنْ رَجُلٍ ‏ ‏أَصَابَتْهُ جَنَابَةٌ وَلَيْسَ عِنْدَهُ مَاءٌ وَعِنْدَهُ ‏ ‏نَبِيذٌ ‏ ‏أَيَغْتَسِلُ بِهِ قَالَ لَا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5846e2e1-c99b-57a6-994e-f1892337cd00', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '81', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْأَرْقَمِ ‏ ‏أَنَّهُ خَرَجَ حَاجًّا ‏ ‏أَوْ مُعْتَمِرًا ‏ ‏وَمَعَهُ النَّاسُ وَهُوَ يَؤُمُّهُمْ فَلَمَّا كَانَ ذَاتَ يَوْمٍ أَقَامَ الصَّلَاةَ صَلَاةَ الصُّبْحِ ثُمَّ قَالَ لِيَتَقَدَّمْ أَحَدُكُمْ وَذَهَبَ إِلَى الْخَلَاءِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَذْهَبَ الْخَلَاءَ وَقَامَتْ الصَّلَاةُ فَلْيَبْدَأْ بِالْخَلَاءِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَى ‏ ‏وُهَيْبُ بْنُ خَالِدٍ ‏ ‏وَشُعَيْبُ بْنُ إِسْحَقَ ‏ ‏وَأَبُو ضَمْرَةَ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَرْقَمَ ‏ ‏وَالْأَكْثَرُ الَّذِينَ رَوَوْهُ عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالُوا كَمَا قَالَ ‏ ‏زُهَيْرٌ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b118a960-ca8b-5a9f-a476-3950d1441c4f', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '82', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏وَمُسَدَّدٌ ‏ ‏وَمُحَمَّدُ بْنُ عِيسَى ‏ ‏الْمَعْنَى ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي حَزْرَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏ابْنُ عِيسَى ‏ ‏فِي حَدِيثِهِ ‏ ‏ابْنُ أَبِي بَكْرٍ ‏ ‏ثُمَّ اتَّفَقُوا أَخُو ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَجِيءَ بِطَعَامِهَا فَقَامَ ‏ ‏الْقَاسِمُ ‏ ‏يُصَلِّي فَقَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُصَلَّى بِحَضْرَةِ الطَّعَامِ وَلَا وَهُوَ يُدَافِعُهُ ‏ ‏الْأَخْبَثَانِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4004027d-0c62-5a7b-975c-cc0d55e75401', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '83', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَيٍّ الْمُؤَذِّنِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ لَا يَحِلُّ لِأَحَدٍ أَنْ يَفْعَلَهُنَّ لَا يَؤُمُّ رَجُلٌ قَوْمًا فَيَخُصُّ نَفْسَهُ بِالدُّعَاءِ دُونَهُمْ فَإِنْ فَعَلَ فَقَدْ خَانَهُمْ وَلَا يَنْظُرُ فِي قَعْرِ بَيْتٍ قَبْلَ أَنْ يَسْتَأْذِنَ فَإِنْ فَعَلَ فَقَدْ دَخَلَ وَلَا ‏ ‏يُصَلِّي وَهُوَ ‏ ‏حَقِنٌ ‏ ‏حَتَّى ‏ ‏يَتَخَفَّفَ ‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ خَالِدٍ السُّلَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْرٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَيٍّ الْمُؤَذِّنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِرَجُلٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ يُصَلِّيَ وَهُوَ ‏ ‏حَقِنٌ ‏ ‏حَتَّى ‏ ‏يَتَخَفَّفَ ‏ ‏ثُمَّ سَاقَ نَحْوَهُ عَلَى هَذَا اللَّفْظِ ‏ ‏قَالَ ‏ ‏وَلَا يَحِلُّ لِرَجُلٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ يَؤُمَّ قَوْمًا إِلَّا بِإِذْنِهِمْ وَلَا يَخْتَصُّ نَفْسَهُ بِدَعْوَةٍ دُونَهُمْ فَإِنْ فَعَلَ فَقَدْ خَانَهُمْ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏هَذَا مِنْ سُنَنِ أَهْلِ ‏ ‏الشَّامِ ‏ ‏لَمْ يُشْرِكْهُمْ فِيهَا أَحَدٌ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8d76b78e-b4fc-5b6c-bcce-65ff59d1a5a0', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '84', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَفِيَّةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bb35ea0b-2b10-51cd-92ac-d42ecd1d35b4', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '85', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('24178e30-24b4-574a-822b-dcf918088304', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '86', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ الْأَنْصَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبَّادَ بْنَ تَمِيمٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ وَهِيَ ‏ ‏أُمُّ عُمَارَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَأُتِيَ بِإِنَاءٍ فِيهِ مَاءٌ قَدْرُ ثُلُثَيْ ‏ ‏الْمُدِّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0a8e0a90-4347-5840-b7df-c5b40fe0f165', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '87', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ الْبَزَّازُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ بِإِنَاءٍ يَسَعُ رَطْلَيْنِ وَيَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏قَالَ عَنْ ‏ ‏ابْنِ جَبْرِ بْنِ عَتِيكٍ ‏ ‏قَالَ ‏ ‏وَرَوَاهُ ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏جَبْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَرَوَاهُ ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏إِلَّا أَنَّهُ قَالَ يَتَوَضَّأُ ‏ ‏بِمَكُّوكٍ ‏ ‏وَلَمْ يَذْكُرْ رَطْلَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏و سَمِعْت ‏ ‏أَحْمَدَ بْنَ حَنْبَلٍ ‏ ‏يَقُولُ ‏ ‏الصَّاعُ خَمْسَةُ أَرْطَالٍ وَهُوَ صَاعُ ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَهُوَ صَاعُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('238842c4-6147-5c29-aec3-56e2057b191a', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '88', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَعَامَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ ‏ ‏سَمِعَ ابْنَهُ يَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْقَصْرَ الْأَبْيَضَ عَنْ يَمِينِ الْجَنَّةِ إِذَا دَخَلْتُهَا فَقَالَ أَيْ بُنَيَّ سَلْ اللَّهَ الْجَنَّةَ وَتَعَوَّذْ بِهِ مِنْ النَّارِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهُ سَيَكُونُ فِي هَذِهِ الْأُمَّةِ قَوْمٌ يَعْتَدُونَ فِي الطَّهُورِ وَالدُّعَاءِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d47eedf9-f34b-5d3d-bf53-fbbf97a1d63b', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '89', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى قَوْمًا ‏ ‏وَأَعْقَابُهُمْ ‏ ‏تَلُوحُ فَقَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('55619542-b5e8-5b9d-8272-d548c5563c6e', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '90', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنِي ‏ ‏صَاحِبٌ لِي ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏تَوْرٍ ‏ ‏مِنْ ‏ ‏شَبَهٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏أَنَّ ‏ ‏إِسْحَقَ بْنَ مَنْصُورٍ ‏ ‏حَدَّثَهُمْ عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f3412baa-6037-54d3-92c2-aeabb052ab71', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '91', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏وَسَهْلُ بْنُ حَمَّادٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏جَاءَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْرَجْنَا لَهُ مَاءً فِي ‏ ‏تَوْرٍ ‏ ‏مِنْ صُفْرٍ فَتَوَضَّأَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0b01252a-8edd-5648-ac30-0b4898a9a84d', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '92', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَلَاةَ لِمَنْ لَا وُضُوءَ لَهُ وَلَا وُضُوءَ لِمَنْ لَمْ يَذْكُرْ اسْمَ اللَّهِ تَعَالَى عَلَيْهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f9b1a7f6-e8a7-5649-b40b-35ab10cf0867', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '93', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏الدَّرَاوَرْدِيِّ ‏ ‏قَالَ وَذَكَرَ ‏ ‏رَبِيعَةُ ‏ ‏أَنَّ تَفْسِيرَ حَدِيثِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا وُضُوءَ لِمَنْ لَمْ يَذْكُرْ اسْمَ اللَّهِ عَلَيْهِ ‏ ‏أَنَّهُ الَّذِي يَتَوَضَّأُ وَيَغْتَسِلُ وَلَا ‏ ‏يَنْوِي وُضُوءًا لِلصَّلَاةِ وَلَا غُسْلًا لِلْجَنَابَةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9767db7b-c2ce-5bf9-b599-4eb090f5e05d', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '94', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏وَأَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ اللَّيْلِ فَلَا يَغْمِسْ يَدَهُ فِي الْإِنَاءِ حَتَّى يَغْسِلَهَا ثَلَاثَ مَرَّاتٍ فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي ‏ ‏بِهَذَا الْحَدِيثِ قَالَ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏أَبَا رَزِينٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0c958be1-5b65-52da-b2ba-9cb5fe189546', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '95', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ ‏ ‏وَمُحَمَّدُ بْنُ سَلَمَةَ الْمُرَادِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْيَمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلَا يُدْخِلْ يَدَهُ فِي الْإِنَاءِ حَتَّى يَغْسِلَهَا ثَلَاثَ مَرَّاتٍ فَإِنَّ أَحَدَكُمْ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏ ‏أَوْ أَيْنَ كَانَتْ تَطُوفُ يَدُهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d24ab6b3-3ef1-5f0e-80f4-703ef14c79be', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '96', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏تَوَضَّأَ فَأَفْرَغَ عَلَى يَدَيْهِ ثَلَاثًا فَغَسَلَهُمَا ثُمَّ تَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ يَدَهُ الْيُمْنَى إِلَى الْمِرْفَقِ ثَلَاثًا ثُمَّ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ مَسَحَ رَأْسَهُ ثُمَّ غَسَلَ قَدَمَهُ الْيُمْنَى ثَلَاثًا ثُمَّ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا ثُمَّ قَالَ ‏ ‏مَنْ تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ وَرْدَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏حُمْرَانُ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏تَوَضَّأَ ‏ ‏فَذَكَرَ نَحْوَهُ وَلَمْ يَذْكُرْ الْمَضْمَضَةَ ‏ ‏وَالِاسْتِنْشَاقَ وَقَالَ فِيهِ وَمَسَحَ رَأْسَهُ ثَلَاثًا ثُمَّ غَسَلَ رِجْلَيْهِ ثَلَاثًا ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ هَكَذَا وَقَالَ مَنْ تَوَضَّأَ دُونَ هَذَا كَفَاهُ وَلَمْ يَذْكُرْ أَمْرَ الصَّلَاةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d9b3f902-c9fb-5139-a7e6-9b07ae28f4b2', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '97', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ دَاوُدَ الْإِسْكَنْدَرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ يُونُسَ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ زِيَادٍ الْمُؤَذِّنُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ الرَّحْمَنِ التَّيْمِيِّ ‏ ‏قَالَ سُئِلَ ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ الْوُضُوءِ ‏ ‏فَقَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏سُئِلَ عَنْ الْوُضُوءِ ‏ ‏فَدَعَا بِمَاءٍ فَأُتِيَ ‏ ‏بِمِيضَأَةٍ ‏ ‏فَأَصْغَاهَا ‏ ‏عَلَى يَدِهِ الْيُمْنَى ثُمَّ أَدْخَلَهَا فِي الْمَاءِ فَتَمَضْمَضَ ثَلَاثًا ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى ثَلَاثًا وَغَسَلَ يَدَهُ الْيُسْرَى ثَلَاثًا ثُمَّ أَدْخَلَ يَدَهُ فَأَخَذَ مَاءً فَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ فَغَسَلَ بُطُونَهُمَا وَظُهُورَهُمَا مَرَّةً وَاحِدَةً ثُمَّ غَسَلَ رِجْلَيْهِ ثُمَّ قَالَ أَيْنَ السَّائِلُونَ عَنْ الْوُضُوءِ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏أَحَادِيثُ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏الصِّحَاحُ كُلُّهَا تَدُلُّ عَلَى مَسْحِ الرَّأْسِ أَنَّهُ مَرَّةً فَإِنَّهُمْ ذَكَرُوا الْوُضُوءَ ثَلَاثًا وَقَالُوا فِيهَا وَمَسَحَ رَأْسَهُ وَلَمْ يَذْكُرُوا عَدَدًا كَمَا ذَكَرُوا فِي غَيْرِهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَلْقَمَةَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏دَعَا بِمَاءٍ فَتَوَضَّأَ فَأَفْرَغَ بِيَدِهِ الْيُمْنَى عَلَى الْيُسْرَى ثُمَّ غَسَلَهُمَا إِلَى الْكُوعَيْنِ قَالَ ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا وَذَكَرَ الْوُضُوءَ ثَلَاثًا قَالَ وَمَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ رِجْلَيْهِ وَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مِثْلَ مَا رَأَيْتُمُونِي تَوَضَّأْتُ ثُمَّ سَاقَ نَحْوَ حَدِيثِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَأَتَمَّ