insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2924e180-17bb-5973-ad3f-a0f2fae116a0', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '98', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ شَقِيقِ بْنِ جَمْرَةَ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏غَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ رَأْسَهُ ثَلَاثًا ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ هَذَا ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏قَالَ ‏ ‏تَوَضَّأَ ثَلَاثًا ‏ ‏فَقَطْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5affdd6b-b864-5cb6-874d-81ab67d6c94e', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '99', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏قَالَ ‏ ‏أَتَانَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَدْ صَلَّى فَدَعَا بِطَهُورٍ فَقُلْنَا مَا يَصْنَعُ ‏ ‏بِالطَّهُورِ ‏ ‏وَقَدْ صَلَّى مَا يُرِيدُ إِلَّا لِيُعَلِّمَنَا فَأُتِيَ بِإِنَاءٍ فِيهِ مَاءٌ وَطَسْتٍ ‏ ‏فَأَفْرَغَ مِنْ الْإِنَاءِ عَلَى يَمِينِهِ فَغَسَلَ يَدَيْهِ ثَلَاثًا ثُمَّ تَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا فَمَضْمَضَ وَنَثَرَ مِنْ الْكَفِّ الَّذِي يَأْخُذُ فِيهِ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى ثَلَاثًا وَغَسَلَ يَدَهُ الشِّمَالَ ثَلَاثًا ثُمَّ جَعَلَ يَدَهُ فِي الْإِنَاءِ فَمَسَحَ بِرَأْسِهِ مَرَّةً وَاحِدَةً ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى ثَلَاثًا وَرِجْلَهُ الشِّمَالَ ثَلَاثًا ثُمَّ قَالَ مَنْ سَرَّهُ أَنْ يَعْلَمَ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهُوَ هَذَا ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ عَلِيٍّ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَلْقَمَةَ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏قَالَ ‏ ‏صَلَّى ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏الْغَدَاةَ ‏ ‏ثُمَّ دَخَلَ الرَّحْبَةَ فَدَعَا بِمَاءٍ فَأَتَاهُ الْغُلَامُ بِإِنَاءٍ فِيهِ مَاءٌ وَطَسْتٍ قَالَ فَأَخَذَ الْإِنَاءَ بِيَدِهِ الْيُمْنَى فَأَفْرَغَ عَلَى يَدِهِ الْيُسْرَى وَغَسَلَ كَفَّيْهِ ثَلَاثًا ثُمَّ أَدْخَلَ يَدَهُ الْيُمْنَى فِي الْإِنَاءِ فَمَضْمَضَ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا ثُمَّ سَاقَ قَرِيبًا مِنْ حَدِيثِ ‏ ‏أَبِي عَوَانَةَ ‏ ‏قَالَ ثُمَّ مَسَحَ رَأْسَهُ مُقَدَّمَهُ وَمُؤَخِّرَهُ مَرَّةً ثُمَّ سَاقَ الْحَدِيثَ نَحْوَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَالِكَ بْنَ عُرْفُطَةَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ خَيْرٍ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أُتِيَ بِكُرْسِيٍّ فَقَعَدَ عَلَيْهِ ثُمَّ أُتِيَ ‏ ‏بِكُوزٍ ‏ ‏مِنْ مَاءٍ فَغَسَلَ يَدَيْهِ ثَلَاثًا ثُمَّ تَمَضْمَضَ مَعَ ‏ ‏الِاسْتِنْشَاقِ بِمَاءٍ وَاحِدٍ وَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبِيعَةُ الْكِنَانِيُّ ‏ ‏عَنْ ‏ ‏الْمِنْهَالِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَسُئِلَ عَنْ وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ وَقَالَ وَمَسَحَ عَلَى رَأْسِهِ حَتَّى لَمَّا يَقْطُرْ وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ هَكَذَا كَانَ وُضُوءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7c2c5f1f-cb42-5eee-9a31-1057b0424784', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '100', '‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ أَيُّوبَ الطُّوسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏فِطْرٌ ‏ ‏عَنْ ‏ ‏أَبِي فَرْوَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ ذِرَاعَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَاحِدَةً ثُمَّ قَالَ هَكَذَا تَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f9afc38d-83d7-5948-b405-a71d1596e068', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '101', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏وَأَبُو تَوْبَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ فَذَكَرَ وُضُوءَهُ كُلَّهُ ثَلَاثًا ثَلَاثًا قَالَ ثُمَّ مَسَحَ رَأْسَهُ ثُمَّ غَسَلَ رِجْلَيْهِ إِلَى الْكَعْبَيْنِ ثُمَّ قَالَ إِنَّمَا أَحْبَبْتُ أَنْ أُرِيَكُمْ طُهُورَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6013fc19-492c-5910-9225-1aaa54267881', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '102', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ يَحْيَى الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ طَلْحَةَ بْنِ يَزِيدَ بْنِ رُكَانَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ الْخَوْلَانِيُّ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيَّ ‏ ‏عَلِيٌّ يَعْنِي ابْنَ أَبِي طَالِبٍ ‏ ‏وَقَدْ ‏ ‏أَهْرَاقَ الْمَاءَ فَدَعَا بِوَضُوءٍ فَأَتَيْنَاهُ ‏ ‏بِتَوْرٍ ‏ ‏فِيهِ مَاءٌ حَتَّى وَضَعْنَاهُ بَيْنَ يَدَيْهِ فَقَالَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَلَا ‏ ‏أُرِيكَ كَيْفَ كَانَ يَتَوَضَّأُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى قَالَ ‏ ‏فَأَصْغَى ‏ ‏الْإِنَاءَ عَلَى يَدِهِ فَغَسَلَهَا ثُمَّ أَدْخَلَ يَدَهُ الْيُمْنَى فَأَفْرَغَ بِهَا عَلَى الْأُخْرَى ثُمَّ غَسَلَ كَفَّيْهِ ثُمَّ تَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثُمَّ أَدْخَلَ يَدَيْهِ فِي الْإِنَاءِ جَمِيعًا فَأَخَذَ بِهِمَا حَفْنَةً مِنْ مَاءٍ فَضَرَبَ بِهَا عَلَى وَجْهِهِ ثُمَّ أَلْقَمَ إِبْهَامَيْهِ مَا أَقْبَلَ مِنْ أُذُنَيْهِ ثُمَّ الثَّانِيَةَ ثُمَّ الثَّالِثَةَ مِثْلَ ذَلِكَ ثُمَّ أَخَذَ بِكَفِّهِ الْيُمْنَى قَبْضَةً مِنْ مَاءٍ فَصَبَّهَا عَلَى ‏ ‏نَاصِيَتِهِ ‏ ‏فَتَرَكَهَا ‏ ‏تَسْتَنُّ ‏ ‏عَلَى وَجْهِهِ ثُمَّ غَسَلَ ذِرَاعَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثًا ثَلَاثًا ثُمَّ مَسَحَ رَأْسَهُ وَظُهُورَ أُذُنَيْهِ ثُمَّ أَدْخَلَ يَدَيْهِ جَمِيعًا فَأَخَذَ حَفْنَةً مِنْ مَاءٍ فَضَرَبَ بِهَا عَلَى رِجْلِهِ وَفِيهَا النَّعْلُ فَفَتَلَهَا بِهَا ثُمَّ الْأُخْرَى مِثْلَ ذَلِكَ قَالَ قُلْتُ وَفِي النَّعْلَيْنِ قَالَ وَفِي النَّعْلَيْنِ قَالَ قُلْتُ وَفِي النَّعْلَيْنِ قَالَ وَفِي النَّعْلَيْنِ قَالَ قُلْتُ وَفِي النَّعْلَيْنِ قَالَ وَفِي النَّعْلَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَحَدِيثُ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏شَيْبَةَ ‏ ‏يُشْبِهُ حَدِيثَ ‏ ‏عَلِيٍّ ‏ ‏لِأَنَّهُ قَالَ فِيهِ ‏ ‏حَجَّاجُ بْنُ مُحَمَّدِ بْنِ جُرَيْجٍ ‏ ‏وَمَسَحَ بِرَأْسِهِ مَرَّةً وَاحِدَةً وَقَالَ ‏ ‏ابْنُ وَهْبٍ ‏ ‏فِيهِ عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏وَمَسَحَ بِرَأْسِهِ ثَلَاثًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f3435769-e80a-5e4d-b861-1a80708b9d2d', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '103', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏وَهُوَ جَدُّ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏هَلْ تَسْتَطِيعُ أَنْ تُرِيَنِي كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏نَعَمْ ‏ ‏فَدَعَا بِوَضُوءٍ فَأَفْرَغَ عَلَى يَدَيْهِ فَغَسَلَ يَدَيْهِ ثُمَّ تَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ إِلَى الْمِرْفَقَيْنِ ثُمَّ مَسَحَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ بَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ثُمَّ غَسَلَ رِجْلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏بِهَذَا الْحَدِيثِ قَالَ فَمَضْمَضَ وَاسْتَنْشَقَ مِنْ كَفٍّ وَاحِدَةٍ يَفْعَلُ ذَلِكَ ثَلَاثًا ثُمَّ ذَكَرَ نَحْوَهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('059ccca8-1672-530a-9457-41a39028d154', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '104', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏حَبَّانَ بْنَ وَاسِعٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدِ بْنِ عَاصِمٍ الْمَازِنِيَّ ‏ ‏يَذْكُرُ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ وُضُوءَهُ وَقَالَ ‏ ‏وَمَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ فَضْلِ يَدَيْهِ وَغَسَلَ رِجْلَيْهِ حَتَّى ‏ ‏أَنْقَاهُمَا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11f1145f-1117-5d93-bbc4-64dbdcdd2617', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '105', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَيْسَرَةَ الْحَضْرَمِيُّ ‏ ‏سَمِعْتُ ‏ ‏الْمِقْدَامَ بْنَ مَعْدِي كَرِبَ الْكِنْدِيَّ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَضُوءٍ فَتَوَضَّأَ ‏ ‏فَغَسَلَ كَفَّيْهِ ثَلَاثًا ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ظَاهِرِهِمَا وَبَاطِنِهِمَا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f92709bc-13f1-5dec-8a9d-c463c2931618', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '106', '‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ خَالِدٍ ‏ ‏وَيَعْقُوبُ بْنُ كَعْبٍ الْأَنْطَاكِيُّ ‏ ‏لَفْظُهُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏حَرِيزِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَلَمَّا بَلَغَ مَسْحَ رَأْسِهِ وَضَعَ كَفَّيْهِ عَلَى مُقَدَّمِ رَأْسِهِ فَأَمَرَّهُمَا حَتَّى بَلَغَ ‏ ‏الْقَفَا ‏ ‏ثُمَّ رَدَّهُمَا إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ‏ ‏قَالَ ‏ ‏مَحْمُودٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَرِيزٌ ‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ خَالِدٍ ‏ ‏وَهِشَامُ بْنُ خَالِدٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏قَالَ وَمَسَحَ بِأُذُنَيْهِ ظَاهِرِهِمَا وَبَاطِنِهِمَا ‏ ‏زَادَ ‏ ‏هِشَامٌ ‏ ‏وَأَدْخَلَ أَصَابِعَهُ فِي ‏ ‏صِمَاخِ ‏ ‏أُذُنَيْهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5328ebe7-6295-560b-b35f-a326995c481e', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '107', '‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ الْفَضْلِ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَزْهَرِ الْمُغِيرَةُ بْنُ فَرْوَةَ ‏ ‏وَيَزِيدُ بْنُ أَبِي مَالِكٍ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏تَوَضَّأَ لِلنَّاسِ كَمَا رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ فَلَمَّا بَلَغَ رَأْسَهُ غَرَفَ غَرْفَةً مِنْ مَاءٍ فَتَلَقَّاهَا بِشِمَالِهِ حَتَّى وَضَعَهَا عَلَى وَسَطِ رَأْسِهِ حَتَّى قَطَرَ الْمَاءُ ‏ ‏أَوْ كَادَ يَقْطُرُ ‏ ‏ثُمَّ مَسَحَ مِنْ مُقَدَّمِهِ إِلَى مُؤَخَّرِهِ وَمِنْ مُؤَخَّرِهِ إِلَى مُقَدَّمِهِ ‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏بِهَذَا الْإِسْنَادِ قَالَ ‏ ‏فَتَوَضَّأَ ثَلَاثًا ثَلَاثًا وَغَسَلَ رِجْلَيْهِ بِغَيْرِ عَدَدٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b1eed0a-fd46-5e6a-b7e5-a0c34d5e805f', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '108', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ابْنِ عَفْرَاءَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِينَا فَحَدَّثَتْنَا أَنَّهُ قَالَ اسْكُبِي لِي وَضُوءًا فَذَكَرَتْ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فِيهِ ‏ ‏فَغَسَلَ كَفَّيْهِ ثَلَاثًا وَوَضَّأَ وَجْهَهُ ثَلَاثًا وَمَضْمَضَ وَاسْتَنْشَقَ مَرَّةً وَوَضَّأَ يَدَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ مَرَّتَيْنِ بِمُؤَخَّرِ رَأْسِهِ ثُمَّ بِمُقَدَّمِهِ وَبِأُذُنَيْهِ كِلْتَيْهِمَا ظُهُورِهِمَا وَبُطُونِهِمَا وَوَضَّأَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَهَذَا مَعْنَى حَدِيثِ ‏ ‏مُسَدَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ عَقِيلٍ ‏ ‏بِهَذَا الْحَدِيثِ يُغَيِّرُ بَعْضَ مَعَانِي ‏ ‏بِشْرٍ ‏ ‏قَالَ فِيهِ وَتَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4580045c-8229-5af6-aad5-58089bbf9943', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '109', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَيَزِيدُ بْنُ خَالِدٍ الْهَمْدَانِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ابْنِ عَفْرَاءَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ عِنْدَهَا فَمَسَحَ الرَّأْسَ كُلَّهُ مِنْ قَرْنِ الشَّعْرِ كُلِّ نَاحِيَةٍ ‏ ‏لِمُنْصَبِّ ‏ ‏الشَّعْرِ لَا يُحَرِّكُ الشَّعْرَ عَنْ هَيْئَتِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9f7e4722-ccec-5b31-a901-8a809da9bb49', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '110', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرٌ يَعْنِي ابْنَ مُضَرَ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏أَنَّ ‏ ‏رُبَيِّعَ بِنْتَ مُعَوِّذٍ ابْنِ عَفْرَاءَ ‏ ‏أَخْبَرَتْهُ قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ قَالَتْ ‏ ‏فَمَسَحَ رَأْسَهُ وَمَسَحَ مَا أَقْبَلَ مِنْهُ وَمَا أَدْبَرَ وَصُدْغَيْهِ وَأُذُنَيْهِ مَرَّةً وَاحِدَةً ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b2922420-f068-595f-9209-5a4161f90518', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '111', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دَاوُدَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ بِرَأْسِهِ مِنْ ‏ ‏فَضْلِ ‏ ‏مَاءٍ كَانَ فِي يَدِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fe0e74fd-95b7-5065-80d8-fa30ac3871ba', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '112', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ابْنِ عَفْرَاءَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَأَدْخَلَ إِصْبَعَيْهِ فِي ‏ ‏حُجْرَيْ أُذُنَيْهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('419b3fb5-4293-5626-b1ee-01dc885aa9e8', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '113', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏وَمُسَدَّدٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ رَأْسَهُ مَرَّةً وَاحِدَةً حَتَّى بَلَغَ الْقَذَالَ ‏ ‏وَهُوَ أَوَّلُ الْقَفَا ‏ ‏وَقَالَ ‏ ‏مُسَدَّدٌ ‏ ‏مَسَحَ رَأْسَهُ مِنْ مُقَدَّمِهِ إِلَى مُؤَخَّرِهِ حَتَّى أَخْرَجَ يَدَيْهِ مِنْ تَحْتِ أُذُنَيْهِ ‏ ‏قَالَ ‏ ‏مُسَدَّدٌ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏يَحْيَى ‏ ‏فَأَنْكَرَهُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏و سَمِعْت ‏ ‏أَحْمَدَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏ابْنَ عُيَيْنَةَ ‏ ‏زَعَمُوا أَنَّهُ كَانَ يُنْكِرُهُ وَيَقُولُ ‏ ‏إِيشْ هَذَا ‏ ‏طَلْحَةُ ‏ ‏عَنْ أَبِيهِ عَنْ جَدِّهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dddde8c8-7401-5ea0-8120-5cb3b0dadd94', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '114', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ فَذَكَرَ الْحَدِيثَ كُلَّهُ ثَلَاثًا ثَلَاثًا قَالَ ‏ ‏وَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ مَسْحَةً وَاحِدَةً ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('97bab4cb-c425-5952-9709-c806eb75f2b6', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '115', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏وَقُتَيْبَةُ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏وَذَكَرَ وُضُوءَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ ‏ ‏الْمَأْقَيْنِ ‏ ‏قَالَ وَقَالَ ‏ ‏الْأُذُنَانِ مِنْ الرَّأْسِ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏يَقُولُهَا ‏ ‏أَبُو أُمَامَةَ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏لَا أَدْرِي هُوَ مِنْ قَوْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مِنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏يَعْنِي قِصَّةَ الْأُذُنَيْنِ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏سِنَانٍ أَبِي رَبِيعَةَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَهُوَ ‏ ‏ابْنُ رَبِيعَةَ ‏ ‏كُنْيَتُهُ ‏ ‏أَبُو رَبِيعَةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('95189221-ae87-5101-b3fb-124622bba1a9', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '116', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ كَيْفَ الطُّهُورُ فَدَعَا بِمَاءٍ فِي إِنَاءٍ ‏ ‏فَغَسَلَ كَفَّيْهِ ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثُمَّ مَسَحَ بِرَأْسِهِ فَأَدْخَلَ إِصْبَعَيْهِ ‏ ‏السَّبَّاحَتَيْنِ ‏ ‏فِي أُذُنَيْهِ وَمَسَحَ بِإِبْهَامَيْهِ عَلَى ظَاهِرِ أُذُنَيْهِ ‏ ‏وَبِالسَّبَّاحَتَيْنِ ‏ ‏بَاطِنَ أُذُنَيْهِ ثُمَّ غَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ هَكَذَا الْوُضُوءُ فَمَنْ زَادَ عَلَى هَذَا أَوْ نَقَصَ فَقَدْ أَسَاءَ وَظَلَمَ ‏ ‏أَوْ ظَلَمَ وَأَسَاءَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('552bcb0d-3888-5067-b9ec-7a785ac81ee9', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '117', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدٌ يَعْنِي ابْنَ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ ثَوْبَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ الْهَاشِمِيُّ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّتَيْنِ مَرَّتَيْنِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f66ee1e9-972d-5bc4-8a03-375c613ec80a', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '118', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏قَالَ قَالَ لَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَتُحِبُّونَ أَنْ أُرِيَكُمْ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ فَدَعَا بِإِنَاءٍ فِيهِ مَاءٌ ‏ ‏فَاغْتَرَفَ غَرْفَةً بِيَدِهِ الْيُمْنَى فَتَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ أَخَذَ أُخْرَى فَجَمَعَ بِهَا يَدَيْهِ ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ أَخَذَ أُخْرَى فَغَسَلَ بِهَا يَدَهُ الْيُمْنَى ثُمَّ أَخَذَ أُخْرَى فَغَسَلَ بِهَا يَدَهُ الْيُسْرَى ثُمَّ قَبَضَ قَبْضَةً مِنْ الْمَاءِ ثُمَّ نَفَضَ يَدَهُ ثُمَّ مَسَحَ بِهَا رَأْسَهُ وَأُذُنَيْهِ ثُمَّ قَبَضَ قَبْضَةً أُخْرَى مِنْ الْمَاءِ فَرَشَّ عَلَى رِجْلِهِ الْيُمْنَى وَفِيهَا النَّعْلُ ثُمَّ مَسَحَهَا بِيَدَيْهِ يَدٍ فَوْقَ الْقَدَمِ وَيَدٍ تَحْتَ النَّعْلِ ثُمَّ صَنَعَ بِالْيُسْرَى مِثْلَ ذَلِكَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
