insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7613b9d7-d61f-5b9d-8540-2be97a93ecd0', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '120', '‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ مَسْعَدَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏لَيْثًا ‏ ‏يَذْكُرُ عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ ‏ ‏يَعْنِي عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَتَوَضَّأُ وَالْمَاءُ يَسِيلُ مِنْ وَجْهِهِ وَلِحْيَتِهِ عَلَى صَدْرِهِ فَرَأَيْتُهُ يَفْصِلُ بَيْنَ الْمَضْمَضَةِ ‏ ‏وَالِاسْتِنْشَاقِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0a6e56d6-c88a-5e6b-bb97-f424b23017b7', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '121', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ ‏ ‏لِيَنْثُرْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('741700b5-28a5-576b-ab62-63a6043dc314', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '122', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏قَارِظٍ ‏ ‏عَنْ ‏ ‏أَبِي غَطَفَانَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَنْثِرُوا ‏ ‏مَرَّتَيْنِ ‏ ‏بَالِغَتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('49ce790e-a31a-5988-b347-f9303fc6eb5a', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '123', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏فِي آخَرِينَ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏لَقِيطِ بْنِ صَبْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ وَافِدَ ‏ ‏بَنِي الْمُنْتَفِقِ ‏ ‏أَوْ فِي وَفْدِ ‏ ‏بَنِي الْمُنْتَفِقِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا قَدِمْنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ نُصَادِفْهُ فِي مَنْزِلِهِ وَصَادَفْنَا ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏قَالَ فَأَمَرَتْ لَنَا ‏ ‏بِخَزِيرَةٍ ‏ ‏فَصُنِعَتْ لَنَا قَالَ وَأُتِينَا بِقِنَاعٍ ‏ ‏وَلَمْ يَقُلْ ‏ ‏قُتَيْبَةُ ‏ ‏الْقِنَاعَ ‏ ‏وَالْقِنَاعُ الطَّبَقُ فِيهِ تَمْرٌ ‏ ‏ثُمَّ جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَلْ أَصَبْتُمْ شَيْئًا ‏ ‏أَوْ أُمِرَ لَكُمْ بِشَيْءٍ ‏ ‏قَالَ قُلْنَا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ فَبَيْنَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُلُوسٌ إِذْ دَفَعَ الرَّاعِي غَنَمَهُ إِلَى ‏ ‏الْمُرَاحِ ‏ ‏وَمَعَهُ سَخْلَةٌ ‏ ‏تَيْعَرُ ‏ ‏فَقَالَ مَا وَلَّدْتَ يَا فُلَانُ قَالَ ‏ ‏بَهْمَةً ‏ ‏قَالَ فَاذْبَحْ لَنَا مَكَانَهَا شَاةً ثُمَّ قَالَ لَا تَحْسِبَنَّ ‏ ‏وَلَمْ يَقُلْ لَا تَحْسَبَنَّ ‏ ‏أَنَّا مِنْ أَجْلِكَ ذَبَحْنَاهَا لَنَا غَنَمٌ مِائَةٌ لَا نُرِيدُ أَنْ تَزِيدَ فَإِذَا وَلَّدَ الرَّاعِي بَهْمَةً ذَبَحْنَا مَكَانَهَا شَاةً قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ لِي امْرَأَةً وَإِنَّ فِي لِسَانِهَا شَيْئًا ‏ ‏يَعْنِي ‏ ‏الْبَذَاءَ ‏ ‏قَالَ فَطَلِّقْهَا إِذًا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ لَهَا صُحْبَةً وَلِي مِنْهَا وَلَدٌ قَالَ فَمُرْهَا يَقُولُ عِظْهَا فَإِنْ يَكُ فِيهَا خَيْرٌ فَسَتَفْعَلْ وَلَا تَضْرِبْ ‏ ‏ظَعِينَتَكَ ‏ ‏كَضَرْبِكَ أُمَيَّتَكَ فَقُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي عَنْ الْوُضُوءِ قَالَ ‏ ‏أَسْبِغْ ‏ ‏الْوُضُوءَ وَخَلِّلْ بَيْنَ الْأَصَابِعِ وَبَالِغْ فِي ‏ ‏الِاسْتِنْشَاقِ إِلَّا أَنْ تَكُونَ صَائِمًا ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ مُكْرَمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَعِيلُ بْنُ كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَافِدِ ‏ ‏بَنِي الْمُنْتَفِقِ ‏ ‏أَنَّهُ أَتَى ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ قَالَ فَلَمْ ‏ ‏يَنْشَبْ ‏ ‏أَنْ جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَقَلَّعُ ‏ ‏يَتَكَفَّأُ ‏ ‏وَقَالَ ‏ ‏عَصِيدَةٌ ‏ ‏مَكَانَ ‏ ‏خَزِيرَةٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏بِهَذَا الْحَدِيثِ قَالَ فِيهِ إِذَا تَوَضَّأْتَ فَمَضْمِضْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3a75cdc3-9adb-5095-9b2e-d84e29198389', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '124', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو تَوْبَةَ يَعْنِي الرَّبِيعَ بْنَ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ زَوْرَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ يَعْنِي ابْنَ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا تَوَضَّأَ أَخَذَ كَفًّا مِنْ مَاءٍ فَأَدْخَلَهُ تَحْتَ حَنَكِهِ فَخَلَّلَ بِهِ لِحْيَتَهُ وَقَالَ هَكَذَا أَمَرَنِي رَبِّي عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَالْوَلِيدُ بْنُ زَوْرَانَ ‏ ‏رَوَى عَنْهُ ‏ ‏حَجَّاجُ بْنُ حَجَّاحٍ ‏ ‏وَأَبُو الْمَلِيحِ الرَّقِّيُّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('26d5544c-edf5-533d-bb39-04626e1d9eb0', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '125', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرِيَّةً ‏ ‏فَأَصَابَهُمْ الْبَرْدُ فَلَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُمْ أَنْ يَمْسَحُوا عَلَى الْعَصَائِبِ ‏ ‏وَالتَّسَاخِينِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('468098ad-024a-57f3-bb66-fdfc0d5dd644', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '126', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْقِلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ وَعَلَيْهِ عِمَامَةٌ ‏ ‏قِطْرِيَّةٌ ‏ ‏فَأَدْخَلَ يَدَهُ مِنْ تَحْتِ الْعِمَامَةِ فَمَسَحَ مُقَدَّمَ رَأْسِهِ وَلَمْ يَنْقُضْ الْعِمَامَةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a3f1ab3-5532-5e05-a2de-5d8e8c279907', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '127', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏الْمُسْتَوْرِدِ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ يَدْلُكُ أَصَابِعَ رِجْلَيْهِ بِخِنْصَرِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('09178c2a-e832-5c44-ad4f-e9d3d9ca0e06', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '128', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبَّادُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏الْمُغِيرَةَ ‏ ‏يَقُولُ ‏ ‏عَدَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَبْلَ الْفَجْرِ فَعَدَلْتُ مَعَهُ ‏ ‏فَأَنَاخَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَبَرَّزَ ثُمَّ جَاءَ فَسَكَبْتُ عَلَى يَدِهِ مِنْ ‏ ‏الْإِدَاوَةِ ‏ ‏فَغَسَلَ كَفَّيْهِ ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ ‏ ‏حَسَرَ ‏ ‏عَنْ ذِرَاعَيْهِ فَضَاقَ كُمَّا جُبَّتِهِ فَأَدْخَلَ يَدَيْهِ فَأَخْرَجَهُمَا مِنْ تَحْتِ الْجُبَّةِ فَغَسَلَهُمَا إِلَى الْمِرْفَقِ وَمَسَحَ بِرَأْسِهِ ثُمَّ تَوَضَّأَ عَلَى خُفَّيْهِ ثُمَّ رَكِبَ فَأَقْبَلْنَا نَسِيرُ حَتَّى نَجِدَ النَّاسَ فِي الصَّلَاةِ قَدْ قَدَّمُوا ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏فَصَلَّى بِهِمْ حِينَ كَانَ وَقْتُ الصَّلَاةِ وَوَجَدْنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَقَدْ رَكَعَ بِهِمْ رَكْعَةً مِنْ صَلَاةِ الْفَجْرِ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَفَّ مَعَ الْمُسْلِمِينَ فَصَلَّى وَرَاءَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏الرَّكْعَةَ الثَّانِيَةَ ثُمَّ سَلَّمَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَلَاتِهِ فَفَزِعَ الْمُسْلِمُونَ فَأَكْثَرُوا التَّسْبِيحَ لِأَنَّهُمْ سَبَقُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالصَّلَاةِ فَلَمَّا سَلَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُمْ قَدْ أَصَبْتُمْ ‏ ‏أَوْ قَدْ أَحْسَنْتُمْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d78f28b1-59aa-58c5-aaad-c35014fdd9c4', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '129', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ ‏ ‏نَاصِيَتَهُ ‏ ‏وَذَكَرَ فَوْقَ الْعِمَامَةِ ‏ ‏قَالَ ‏ ‏عَنْ ‏ ‏الْمُعْتَمِرِ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَمْسَحُ عَلَى الْخُفَّيْنِ وَعَلَى ‏ ‏نَاصِيَتِهِ ‏ ‏وَعَلَى عِمَامَتِهِ ‏ ‏قَالَ ‏ ‏بَكْرٌ ‏ ‏وَقَدْ ‏ ‏سَمِعْتُهُ مِنِ ‏ ‏ابْنِ الْمُغِيرَةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a0c0efd-ab7d-5419-bb3a-ea46493a1090', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '130', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏رَكْبِهِ ‏ ‏وَمَعِي ‏ ‏إِدَاوَةٌ ‏ ‏فَخَرَجَ لِحَاجَتِهِ ثُمَّ أَقْبَلَ فَتَلَقَّيْتُهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏فَأَفْرَغْتُ عَلَيْهِ فَغَسَلَ كَفَّيْهِ وَوَجْهَهُ ثُمَّ أَرَادَ أَنْ يُخْرِجَ ذِرَاعَيْهِ وَعَلَيْهِ جُبَّةٌ مِنْ صُوفٍ مِنْ جِبَابِ ‏ ‏الرُّومِ ‏ ‏ضَيِّقَةُ الْكُمَّيْنِ فَضَاقَتْ ‏ ‏فَادَّرَعَهُمَا ‏ ‏ادِّرَاعًا ثُمَّ أَهْوَيْتُ إِلَى الْخُفَّيْنِ لِأَنْزَعَهُمَا فَقَالَ لِي ‏ ‏دَعْ الْخُفَّيْنِ فَإِنِّي أَدْخَلْتُ الْقَدَمَيْنِ الْخُفَّيْنِ وَهُمَا طَاهِرَتَانِ فَمَسَحَ عَلَيْهِمَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏شَهِدَ لِي ‏ ‏عُرْوَةُ ‏ ‏عَلَى ‏ ‏أَبِيهِ ‏ ‏وَشَهِدَ ‏ ‏أَبُوهُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَعَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏قَالَ ‏ ‏تَخَلَّفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ هَذِهِ الْقِصَّةَ قَالَ فَأَتَيْنَا النَّاسَ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏يُصَلِّ بِهِمْ الصُّبْحَ فَلَمَّا رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ أَنْ يَتَأَخَّرَ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ أَنْ يَمْضِيَ قَالَ فَصَلَّيْتُ أَنَا وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَلْفَهُ رَكْعَةً فَلَمَّا سَلَّمَ قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى الرَّكْعَةَ الَّتِي سُبِقَ بِهَا وَلَمْ يَزِدْ عَلَيْهَا ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏وَابْنُ الزُّبَيْرِ ‏ ‏وَابْنُ عُمَرَ ‏ ‏يَقُولُونَ ‏ ‏مَنْ أَدْرَكَ الْفَرْدَ مِنْ الصَّلَاةِ عَلَيْهِ سَجْدَتَا السَّهْوِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2ceb7460-1cfb-573d-a246-3fb015942ddc', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '131', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ يَعْنِي ابْنَ حَفْصِ بْنِ عُمَرَ بْنِ سَعْدٍ ‏ ‏سَمِعَ ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏أَنَّهُ شَهِدَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏يَسْأَلُ ‏ ‏بِلَالًا ‏ ‏عَنْ وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ ‏ ‏يَخْرُجُ يَقْضِي حَاجَتَهُ ‏ ‏فَآتِيهِ بِالْمَاءِ فَيَتَوَضَّأُ وَيَمْسَحُ عَلَى عِمَامَتِهِ ‏ ‏وَمُوقَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏هُوَ ‏ ‏أَبُو عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏بَنِي تَيْمِ بْنِ مُرَّةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('10c8ac5c-132a-5e53-bcd6-465204627280', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '132', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْحُسَيْنِ الدِّرْهَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ دَاوُدَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏أَنَّ ‏ ‏جَرِيرًا ‏ ‏بَالَ ثُمَّ ‏ ‏تَوَضَّأَ فَمَسَحَ عَلَى الْخُفَّيْنِ وَقَالَ مَا يَمْنَعُنِي أَنْ أَمْسَحَ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ قَالُوا إِنَّمَا كَانَ ذَلِكَ قَبْلَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏ ‏قَالَ مَا أَسْلَمْتُ إِلَّا بَعْدَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2b9a0af9-f655-54cf-9bc8-60757beec111', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '133', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏وَأَحْمَدُ بْنُ أَبِي شُعَيْبٍ الْحَرَّانِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏دَلْهَمُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏حُجَيْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏النَّجَاشِيَّ ‏ ‏أَهْدَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُفَّيْنِ أَسْوَدَيْنِ ‏ ‏سَاذَجَيْنِ ‏ ‏فَلَبِسَهُمَا ثُمَّ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَيْهِمَا ‏ ‏قَالَ ‏ ‏مُسَدَّدٌ ‏ ‏عَنْ ‏ ‏دَلْهَمِ بْنِ صَالِحٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏هَذَا مِمَّا تَفَرَّدَ بِهِ أَهْلُ ‏ ‏الْبَصْرَةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
